const sketch = (p5obj:any) => {
/**************************************************************
Sakuhin Caption...
オイルタイマーを書きました。一秒とにオイルが一滴落ち、一分で
下にたまっていたオイルが融合して、右下にたまっていき、一時間で
すべてのオイルが落ち切ってランダムな色に変わって再びオイルが満たされて
落ちていきます。
 **************************************************************/
/**
  デバッグ機能
    'S'キー：png出力
    'H'キー：時が変わったときのアニメーション再生
    'M'キー：分が変わったときのアニメーション再生
*/
// === 'S'キーを押した時の出力画像名 ===
//  "K3_[クラス][番号]_[苗字].png"
let pngName: String = "K3_D02_Fukushima.png";

// === アニメーション用変数/定数 ===



// === Time Handling ===
let hourCurrent: number = 0;       // 現在の時（0~23）
let minuteCurrent: number = 0;     // 現在の分（0~59）
let secondCurrent: number = 0;     // 現在の秒（0~59）
let deltaTime: number = 0;       // 前フレームからの経過時間（秒,0~1）
let deltaTimePerSec: number = 0; // 前回の秒が切り替わってからの経過時間（秒,0~1）
let isHourAnim: number = 0;    // アニメーションフラグ（1:アニメーション中）
let isMinuteAnim: number = 0;
let isSecondAnim: number = 0;

/*落ちていくオイルの描画に使う変数*/
let maxDrops: number = 100;
let dropX: number[] = new Array(maxDrops);
let dropY: number[] = new Array(maxDrops);
let dropSpeed: number[] = new Array(maxDrops);
let  dropActive: Boolean[] = new Array(maxDrops);
let dropPhase: number[] = new Array(maxDrops);  // フェーズを記録
let storedDrops: number[][] = Array.from({ length: 1000 }, () => Array(2).fill(0)); // 落ちてきた粒の座標
let storedCount: number = 0;                        // たまった粒の数
let isOilSolid: boolean = false;                // 一つの塊になっているか


 
p5obj.setup = (): void =>
{
  p5obj.createCanvas( 600, 1000 );
  p5obj.frameRate( 30 );  // フレームレートの指定
  
  for( let i = 0; i < maxDrops; i++) {
  dropActive[i] = false;
}

  // === Time Init ===
  p5obj.initTime();

  isHourAnim = 1;
}

p5obj.draw = (): void =>
{  
  // === Time Update ===
  p5obj.updateTimePre();
  
  //hourCurrent = 1;  // 時 を指定して描画を確認したい場合に一時的に有効化
  
  // === 画面のクリア ===
  
  // 画面をクリア
  p5obj.fill( 255 );
  p5obj.noStroke();
  p5obj.rect( 0, 0, p5obj.width, p5obj.height );

  // 既定の描画カラーに戻す．
  p5obj.fill( 255 );
  p5obj.stroke( 0 );
  
  // === アニメーションを記述 ===
  oH = 50 + secondCurrent*0.0847222222 + minuteCurrent*5.08333333; //オイルの水位
  mX = 50*p5obj.pow( 1.0391, minuteCurrent );
  mY = 50*p5obj.pow( 1.03225, minuteCurrent );
  
  if (secondCurrent == 12) //オイルが角まで移動すると溜まっているオイルが大きくなる
  {
    mX = mX*1.0391;
    mY = mY*1.03225;
    
    iX = 75;
  }


  p5obj.drawOil();
  p5obj.drawSunadokei();
  p5obj.dropOil();
  p5obj.drawStoredOil();
  p5obj.drawMargedOil();
  
  if (secondCurrent < 12) //分が変わるとオイルの塊が角に向かって移動する
  {
    p5obj.drawIdouOil();
  }
  
  // 秒が変化した時のアニメーション
  if ( secondCurrent != secondPrev )
  {
    isSecondAnim = 1;  // アニメーション開始
    
    // アニメーション初期化
    
    
  }
  if ( isSecondAnim == 1 )  // アニメーション中
  {
    // アニメーション中の処理を記述
    if (minuteCurrent != 0) //一時間で溜まったオイルが落ちきるように一秒ごとに水位が変化
    {
      oH += 0.0847222222;
    }
    else
    {
      oH = 50;
    }
    
    if (minuteCurrent > 49) //砂時計の形に沿うようにオイルの描画に使う変数の値を変化させる
    {
      oX = 9*oH - 2650;
      oY = oH;
      
      if (oX > 500)
      { oX = 500;}
    }
    if (minuteCurrent == 0)
    {
      oX = 50;
      oY = 300;
    }
    
 
    isSecondAnim = 0;  // アニメーション終了
  }
  

  
  
  // 分が変化した時のアニメーション
  if ( minuteCurrent != minutePrev )
  {
    isMinuteAnim = 1;  // アニメーション開始
    
    // アニメーション初期化
    
    
  }
  if( isMinuteAnim == 1 )  // アニメーション中
  {
    // アニメーション中の処理を記述
    // ▼ 分が変わったらオイルをリセット
    storedCount = 0;
    isOilSolid = false;
    
    isMinuteAnim = 0;  // アニメーション終了
  }
  
  
  // 時が変化した時のアニメーション
  if ( hourCurrent != hourPrev )
  {
    isHourAnim = 1;  // アニメーションの開始
    
    // アニメーション初期化
    
    
  }
  if( isHourAnim == 1 )
  {
    // アニメーション中の処理を記述
    
    oR = p5obj.random(255);
    oG = p5obj.random(255);
    oB = p5obj.random(255);
    
    isHourAnim = 0;  // アニメーション終了
  }
  
  
  // === Time Update ===
  p5obj.updateTimePost();
}
let oR: number;
let oG: number;
let oB: number;



/*砂時計の描画に使う変数*/
let sRX: number = 50; //rectのX座標
let sRY: number = 50; //rectのY座標
let sRW: number = 500; //rectの幅
let sRH: number = 900; //rectの高さ
let sLSX1: number = 50;//p5obj.line(1)の始点のX座標
let sLSY1: number = 300;//p5obj.line(1)の始点のY座標
let sLEX1: number = 500;//p5obj.line(1)の終点のX座標
let sLEY1: number = 350;//p5obj.line(1)の終点のY座標
let sLSX2: number = 100;//p5obj.line(2)の始点のX座標
let sLSY2: number = 700;//p5obj.line(2)の始点のY座標
let sLEX2: number = 550;//p5obj.line(2)の終点のX座標
let sLEY2: number = 650;//p5obj.line(2)の終点のY座標  

p5obj.drawSunadokei = (): void => //砂時計の描画
{
  p5obj.noFill();
  p5obj.rect( sRX, sRY, sRW, sRH );
  p5obj.line(sLSX1,sLSY1,sLEX1,sLEY1);
  p5obj.line(sLSX2,sLSY2,sLEX2,sLEY2);  
}

/*溜まっているオイルの描画に使う変数*/
let oH: number = 50 + secondCurrent*0.0847222222 + minuteCurrent*5.08333333; //オイルの水位
let oX: number = 50; //オイルの始点のX座標
let oY: number = 300; //オイルの左下のY座標

p5obj.drawOil = (): void => //溜まっているオイルの描画
{
  p5obj.fill(oR,oG,oB);
  p5obj.beginShape();
  p5obj.vertex(oX,oH);
  p5obj.vertex(550,oH);
  p5obj.vertex(550,355);
  p5obj.vertex(oX,oY);
  p5obj.endShape();  
}


p5obj.dropOil = (): void => //落ちていくオイルの描画
{
  // 1秒に1粒発生
  if (p5obj.frameCount % 30 == 0) 
  {
    for( let i = 0; i < maxDrops; i++) 
    {
      if (!dropActive[i]) 
      {
        dropX[i] = p5obj.random(510, 540);
        dropY[i] = 360;
        dropSpeed[i] = p5obj.random(1.5, 2.5);
        dropPhase[i] = 0; // 初期は落下中
        dropActive[i] = true;
        break;
      }
    }
  }

  for( let i = 0; i < maxDrops; i++) 
  {
    if (dropActive[i]) 
    {
let x: number = dropX[i];

      if (dropPhase[i] == 0) 
      {
        // ▼ フェーズ0: 垂直に落ちる
        dropY[i] += dropSpeed[i];
        if (dropY[i] >= 655) 
        {
          dropPhase[i] = 1; // 斜線モードへ
        }

      } else if (dropPhase[i] == 1) 
      {
        // ▼ フェーズ1: 斜線のやや上を沿うように左下に流れる

        // 線のy座標
let yLine: number = -1.0/9 * (x - 100) + 700;
let yLimit: number = yLine - 10;

        dropX[i] -= 2.0;
        if (dropY[i] < yLimit) 
        {
          dropY[i] += 0.5;
        } else 
        {
          dropY[i] = yLimit;
        }

        // 左端に達したら再落下
        if (dropX[i] <= 100) 
        {
          dropPhase[i] = 2;
        }

      } 
      else if (dropPhase[i] == 2) 
      {
        // ▼ フェーズ2: 再度真下に落ちる
        dropY[i] += dropSpeed[i];
      }

      // 描画
      p5obj.fill(oR, oG, oB, 100);
      p5obj.noStroke();
      p5obj.circle(dropX[i], dropY[i], 10);  // サイズ10に変更

      // 画面外に出たら消滅
      if (dropY[i] > 940) 
      {
        dropActive[i] = false;

        // 粒の位置を計算して格納（左下に順番に並べる）
let col: number = storedCount % 10;      // 0〜9 列（横方向）
let row: number = storedCount / 10;      // 上から何段目か
let sx: number = 55 + col * 10;        // x座標（55, 65, ..., 145）
let sy: number = 945 - row * 10;       // y座標（945から段ごとに上がる）

        storedDrops[storedCount][0] = sx;
        storedDrops[storedCount][1] = sy;
        storedCount++;
      }
    }
  }
}

/*溜まっていくオイルの描画に使う変数*/
let dDX: number = 55 ;
let dDY: number = 945 ;
let dDi: number;
let pI: number;

p5obj.droppedOil = (): void =>
{
  for( let dDi = 0 ;dDi<pI;dDi++)
  {
      if ( dDX < 150)
    {
      p5obj.circle(dDX,dDY,10);
    
      dDX += 10;
    }
    else
    {
      dDX = 55;
    
      if (minuteCurrent == 0)
      {
        dDY = 945;
      }
      else
      {
        dDY -= 10;
      }
    }
  }
  pI = dDi+1;
}

p5obj.drawStoredOil = (): void =>
{
  if (!isOilSolid) 
  {
    for( let i = 0; i < storedCount; i++) 
    {
      p5obj.fill(oR, oG, oB, 150);
      p5obj.noStroke();
      p5obj.circle(storedDrops[i][0], storedDrops[i][1], 10);
    }
  } else 
  {
    p5obj.fill(oR, oG, oB);
    p5obj.noStroke();
    p5obj.ellipse(300, 970, 200, 40); // 中央に塊
  }
}

/*融合したオイルの描画で使う変数*/
let mX: number;
let mY: number;

p5obj.drawMargedOil = (): void => //融合したオイルの描画
{
  p5obj.arc( 550, 950, mX, mY, p5obj.radians( 180 ), p5obj.radians( 270 ), p5obj.PIE );  
}

/*角に移動していくオイルの描画に使う変数*/
let iX: number = 75;

p5obj.drawIdouOil = (): void => //角に移動していくオイルの描画
{
  if(iX<490)
  {
    p5obj.ellipse(iX,925 , 50, 50);
    iX++;
  }
  else
  {
    iX = 75;
  }
    
}
let rR: number;

p5obj.reverse = (): void => 
{
  p5obj.push(); 
  for( let rR = 0; rR < 361; rR++)
  { 
    p5obj.rotate(p5obj.radians(rR));
  }
  p5obj.pop(); 
}


// === Time Handling ===
let hourPrev: number;
let minutePrev: number;
let secondPrev: number;
let millisCurrent: number;
let millisPrev: number;
let millisPrevSec: number;
// === Time Handling Functions===
p5obj.initTime = (): void =>
{
  hourCurrent = p5obj.hour();
  minuteCurrent = p5obj.minute();
  secondCurrent = p5obj.second();
  millisCurrent = p5obj.millis();
  
  hourPrev = p5obj.hour();
  minutePrev = p5obj.minute();
  secondPrev = p5obj.second();
  millisPrev = p5obj.millis();
  
  millisPrevSec = p5obj.millis();
}
p5obj.updateTimePre = (): void =>
{ 
  if( hourPrev != p5obj.hour() ) hourCurrent = p5obj.hour();
  if( minutePrev != p5obj.minute() ) minuteCurrent = p5obj.minute();
  secondCurrent = p5obj.second();
  millisCurrent = p5obj.millis();
  
  deltaTime = ( millisCurrent - millisPrev ) / 1000;
  
  if ( secondCurrent != secondPrev )
  {
    millisPrevSec = p5obj.millis();
  }
  
  deltaTimePerSec = ( millisCurrent - millisPrevSec ) / 1000;
}
p5obj.updateTimePost = (): void =>
{ 
  hourPrev = hourCurrent;
  minutePrev = minuteCurrent;
  secondPrev = secondCurrent;
  millisPrev = millisCurrent;
}
p5obj.keyPressed = (): void =>
{
  if ( p5obj.key == 's' )
  {
    p5obj.save(pngName);
  }
  else if ( p5obj.key == 'h' )
  {
    hourPrev = -1;
  }
  else if ( p5obj.key == 'm' )
  {
    minutePrev = -1;
  }
}

};

export default sketch;
