const sketch = (p5obj:any) => {
/**************************************************************
 電車の窓からみえる、通過していく景色を表現した。
 時で明るさ、分で山、秒で雲が変化し、電柱は１秒おきに通過する。
 三角関数を用いて時間帯の明るさを調整したり、for文を用いて連続する田んぼを表現したりした。
 
 **************************************************************/
/**
 デバッグ機能
 'S'キー：png出力
 'H'キー：時が変わったときのアニメーション再生
 'M'キー：分が変わったときのアニメーション再生
 */
// === 'S'キーを押した時の出力画像名 ===
//  "K3_[クラス][番号]_[苗字].png"
let pngName: String = "K3_A12_fukushima.png";

// === アニメーション用変数/定数 ===
let count: number =0;

// === Time Handling ===
let hourCurrent: number;       // 現在の時（0~23）
let minuteCurrent: number;     // 現在の分（0~59）
let secondCurrent: number;     // 現在の秒（0~59）
let deltaTime: number;       // 前フレームからの経過時間（秒,0~1）
let deltaTimePerSec: number; // 前回の秒が切り替わってからの経過時間（秒,0~1）
let isHourAnim: number = 0;    // アニメーションフラグ（1:アニメーション中）
let isMinuteAnim: number = 0;
let isSecondAnim: number = 0;

p5obj.setup = (): void =>
{
  p5obj.createCanvas( 400, 300 );
  p5obj.frameRate( 60 );  // フレームレートの指定

  // === Time Init ===
  p5obj.initTime();
}

p5obj.draw = (): void =>
{
  // === Time Update ===
  p5obj.updateTimePre();

  //hourCurrent = 1;  // 時 を指定して描画を確認したい場合に一時的に有効化

  // === アニメーションを記述 ===

  p5obj.background(180, 80, 80);
  p5obj.translate(200, 125);
  p5obj.noStroke();
  p5obj.strokeWeight(1);

  //１時間おきに通過する山↓
let yama: number = minuteCurrent*10+secondCurrent/6;
  p5obj.fill(50, 80, 50);
  p5obj.triangle(150-yama, 20, 450-yama, 20, 300-yama, -40);

  //１分おきに通過する雲↓
let kumo: number = secondCurrent*10+deltaTimePerSec*10;
  p5obj.fill(200, 100, 50);
  p5obj.ellipse(300-kumo, -65, 300, 15);

  //田んぼと土手↓
let tanbok: number = 60;
let tanbo: number = (count*4)%tanbok;
  p5obj.stroke(0);
  for( let mai = 0; mai <= 330; mai+=30) {
    p5obj.fill(180, 235, 100);
    p5obj.quad(-150-tanbo+mai, 20, -120-tanbo+mai, 20, (-120-tanbo+mai)*4, 100, (-150-tanbo+mai)*4, 100);
  }
  p5obj.fill(160, 185, 120);
  p5obj.rect(-200, 80, 400, 20); //土手

  //１秒おきに通過する電柱と電線↓
let denchuk: number = 900;
let denchu: number = (count*15)%denchuk;
  p5obj.noFill();
  p5obj.strokeWeight(2);
  p5obj.arc(-denchu+300, -80, denchuk, 80, p5obj.radians(0), p5obj.radians(180));
  p5obj.arc(-denchu+1200, -80, denchuk, 80, p5obj.radians(0), p5obj.radians(180));
  p5obj.arc(-denchu+300, -60, denchuk, 80, p5obj.radians(0), p5obj.radians(180));
  p5obj.arc(-denchu+1200, -60, denchuk, 80, p5obj.radians(0), p5obj.radians(180));
  p5obj.strokeWeight(6);
  p5obj.line(-denchu+750, -80, -denchu+750, 80);

  //時間帯によって暗くなるフィルタ↓

  p5obj.noStroke();
  p5obj.fill(0, (1+p5obj.cos(p5obj.radians(hourCurrent*15)))*80);
  p5obj.rect(-150, -100, 300, 200);

  //車内↓

  p5obj.noStroke();
  p5obj.fill(220);
  p5obj.rect(-200, -125, 400, 25);
  p5obj.rect(-200, -125, 50, 300);
  p5obj.rect(150, -125, 50, 300);
  p5obj.rect(-200, 100, 400, 75);

  p5obj.fill(100, 50, 80);
  p5obj.rect(-200, 115, 400, 75);

  p5obj.fill(150);
  p5obj.rect(-135, -125, 5, 300);
  p5obj.rect(130, -125, 5, 300);
  p5obj.rect(-200, -125, 400, 5);
  p5obj.rect(-200, -115, 400, 5);



  count ++;


  // 秒が変化した時のアニメーション
  if ( secondCurrent != secondPrev )
  {
    isSecondAnim = 1;  // アニメーション開始

    // アニメーション初期化
  }
  if ( isSecondAnim == 1 )  // アニメーション中
  {
    // アニメーション中の処理を記述



    isSecondAnim = 0;  // アニメーション終了
  }


  // 分が変化した時のアニメーション
  if ( minuteCurrent != minutePrev )
  {
    isMinuteAnim = 1;  // アニメーション開始

    // アニメーション初期化
  }
  if ( isMinuteAnim == 1 )  // アニメーション中
  {
    // アニメーション中の処理を記述



    isMinuteAnim = 0;  // アニメーション終了
  }


  // 時が変化した時のアニメーション
  if ( hourCurrent != hourPrev )
  {
    isHourAnim = 1;  // アニメーションの開始

    // アニメーション初期化
  }
  if ( isHourAnim == 1 )
  {
    // アニメーション中の処理を記述



    isHourAnim = 0;  // アニメーション終了
  }

  // 時間をデバッグ表示（ 提出前に非表示にすること．）

  /*
   p5obj.fill( 0 );
   p5obj.textSize(20);
   p5obj.text( hourCurrent + ":" + minuteCurrent + ":" + secondCurrent, 10, 20);
   p5obj.text( "deltaTimePerSec: " + deltaTimePerSec, 10, 40);
   p5obj.text( "deltaTime: " + deltaTime, 10, 60);
   */

  // === Time Update ===
  p5obj.updateTimePost();
}

// === Time Handling ===
let hourPrev: number;
let minutePrev: number;
let secondPrev: number;
let millisCurrent: number;
let millisPrev: number;
let millisPrevSec: number;
// === Time Handling Functions===
p5obj.initTime = (): void =>
{
  hourCurrent = p5obj.hour();
  minuteCurrent = p5obj.minute();
  secondCurrent = p5obj.second();
  millisCurrent = p5obj.millis();
  
  hourPrev = p5obj.hour();
  minutePrev = p5obj.minute();
  secondPrev = p5obj.second();
  millisPrev = p5obj.millis();
  
  millisPrevSec = p5obj.millis();
}
p5obj.updateTimePre = (): void =>
{ 
  if( hourPrev != p5obj.hour() ) hourCurrent = p5obj.hour();
  if( minutePrev != p5obj.minute() ) minuteCurrent = p5obj.minute();
  secondCurrent = p5obj.second();
  millisCurrent = p5obj.millis();
  
  deltaTime = ( millisCurrent - millisPrev ) / 1000;
  
  if ( secondCurrent != secondPrev )
  {
    millisPrevSec = p5obj.millis();
  }
  
  deltaTimePerSec = ( millisCurrent - millisPrevSec ) / 1000;
}
p5obj.updateTimePost = (): void =>
{ 
  hourPrev = hourCurrent;
  minutePrev = minuteCurrent;
  secondPrev = secondCurrent;
  millisPrev = millisCurrent;
}
p5obj.keyPressed = (): void =>
{
  if ( p5obj.key == 's' )
  {
    p5obj.save(pngName);
  }
  else if ( p5obj.key == 'h' )
  {
    hourPrev = -1;
  }
  else if ( p5obj.key == 'm' )
  {
    minutePrev = -1;
  }
}


};

export default sketch;
