const sketch = (p5obj:any) => {
p5obj.setup = () => 
{
  p5obj.createCanvas( 1000, 1000 );
  p5obj.noLoop();
}

p5obj.draw = () => 
{
  //床を描写
  for( let iF: number = 0; iF < 1000; iF += 200 )
  {
    Floor( iF, p5obj.random(-600,-200), 600, 4 );
  }
  //ホコリを描写
  for( let iD: number = 0; iD < 50; iD ++ )
  {
    Dust( p5obj.random( 1000 ), p5obj.random( 1000 ), p5obj.random( 3, 5 ), 12 );
  }
  p5obj.save("sk_k4_23_B03.png");
}

const Dust = (BeginX: number, BeginY: number, nagasa: number, iLevel: number) => {
  p5obj.strokeWeight( 0.01 );  //ホコリの糸くずは細く
  p5obj.stroke( p5obj.random( 255 ), p5obj.random( 255 ), p5obj.random( 255 ) );  //ホコリの糸くず一本一本はカラフルに
  
  let EndX: number = BeginX + nagasa * p5obj.random( -20, 20 );
  let EndY: number = BeginY + nagasa * p5obj.random( -20, 20 );
  
  p5obj.line( BeginX, BeginY, EndX, EndY );
  
  if( iLevel > 1 )
  {
    Dust( EndX, EndY, nagasa * 0.8, iLevel - 1 );
    Dust( EndX, EndY, nagasa * 0.8, iLevel - 1 );
  }
}

const Floor = (hidariueX: number, hidariueY: number, nagasa: number, iLevel: number) => {
  p5obj.rectMode(p5obj.CORNERS); 
  p5obj.strokeWeight( 0.8 );
  p5obj.stroke(36, 22, 22);
  p5obj.fill( p5obj.random( 55,65 ), p5obj.random( 40  , 44 ), p5obj.random( 27, 33 ) );  //フローリングの板材の色を変更
  
  let migisitaX: number = hidariueX + 200;  //フローリングの幅は200に固定
  let migisitaY: number = hidariueY + nagasa + p5obj.random( -200, 200 );  //フローリングの長さをランダムに
  
  p5obj.rect( hidariueX, hidariueY, migisitaX, migisitaY );
  
  if( iLevel > 1 )
  {
    Floor( hidariueX, migisitaY, 600, iLevel - 1 );
  }
}


const keyPressed = () => {
  if( p5obj.keyCode == p5obj.UP )
  {
    p5obj.save("kadaishashin.png");
  }
  else
  {
    p5obj.redraw();
  }
}

};

export default sketch;
