import p5 from "p5";

const sketch = (p5obj:any) => {
/**************************************************************
Sakuhin Caption...
バイクが街を走る姿。
秒ごとにタイヤが一周し、分ごとに、背景の中に茶色いビルが現れる、時間ごとに空の色、ビルの窓の色が変化する。

 **************************************************************/
/**
  デバッグ機能
    'S'キー：png出力
    'H'キー：時が変わったときのアニメーション再生
    'M'キー：分が変わったときのアニメーション再生
*/
// === 'S'キーを押した時の出力画像名 ===
//  "K3_[クラス][番号]_[苗字].png"
let pngName: String = "K3_A12_fukushima.png"; // 'S'キーを押した時の出力画像名

// === アニメーション用変数/定数 ===
let buildingX: number[] = [
  100, 200, 300, 400, 500
]; // 建物の初期位置
let bikeSpeed: number = 12; // バイクの速度
let angle: number = 0;
let groundLevel: number = 220; // 地面の高さ

// === Time Handling ===
let hourCurrent: number;       // 現在の時（0~23）
let minuteCurrent: number;     // 現在の分（0~59）
let secondCurrent: number;     // 現在の秒（0~59）
let deltaTime: number;       // 前フレームからの経過時間（秒,0~1）
let deltaTimePerSec: number; // 前回の秒が切り替わってからの経過時間（秒,0~1）
let isHourAnim: number = 0;    // アニメーションフラグ（1:アニメーション中）
let isMinuteAnim: number = 0;
let isSecondAnim: number = 0;



p5obj.setup = (): void => {
  p5obj.createCanvas(340, 400);
  p5obj.frameRate(30);  // フレームレートの指定
   // === Time Init ===
  p5obj.initTime();
}
  
// ============ アニメーションを記述 =============
  // hourCurrent = 1;  // 時 を指定して描画を確認したい場合に一時的に有効化
p5obj.drawBuilding = (x: number, bottomY: number, w: number, h: number, c:p5.Color ): void => {
  p5obj.fill(c);
  p5obj.noStroke();
  p5obj.rect(x, bottomY - h, w, h); // bottomY - h でビルの上端を計算
}

p5obj.drawWindows = (x: number, bottomY: number, w: number, h: number, wx: number, wy: number, c:p5.Color ): void => {
  p5obj.fill(c);
  p5obj.noStroke();
let rows: number = h / wy;
let cols: number = w / wx;
  for( let i = 0; i < rows; i++) {
    for( let j = 0; j < cols; j++) {
      p5obj.rect(x + j * wx + wx * 0.2, bottomY - h + i * wy + wy * 0.2, wx * 0.6, wy * 0.6);
    }
  }
}

p5obj.updateCurrentTime = (): void => {
let newSecond: number = p5obj.second();
  if (newSecond != secondCurrent) {
    secondCurrent = newSecond;
    deltaTimePerSec = 0;
  } else {
    deltaTimePerSec += deltaTime;
  }
  deltaTime = 1.0 / p5obj.frameRate;
  hourCurrent = p5obj.hour();
  minuteCurrent = p5obj.minute();
}

p5obj.drawBackground = (): void => {
  p5obj.updateCurrentTime();
let iB: number = secondCurrent + 60 * minuteCurrent + 3600 * hourCurrent;
  let bgR: number = 0;
  let bgG: number = 0;
  let bgB: number = 0;

  if (4 <= hourCurrent && hourCurrent < 8) {
    bgR =((iB - 14400) * 144 / 14400);
    bgG =((iB - 14400) * 215 / 14400);
    bgB =(80 + (iB - 14400) * 156 / 14400);
    p5obj.background(bgR, bgG, bgB);
  } else if (8 <= hourCurrent && hourCurrent < 16) {
    bgR = 144;
    bgG = 215;
    bgB = 236;
    p5obj.background(bgR, bgG, bgB);
  } else if (16 <= hourCurrent && hourCurrent < 20) {
    bgR =(144 - (iB - 57600) * 144 / 14400);
    bgG =(215 - (iB - 57600) * 215 / 14400);
    bgB =(236 - (iB - 57600) * 156 / 14400);
    p5obj.background(bgR, bgG, bgB);
  } else {
    bgR = 0;
    bgG = 0;
    bgB = 80;
    p5obj.background(bgR, bgG, bgB);
  }

  // 窓の色を背景が暗い時に変更
  let windowColor = (hourCurrent < 4 || hourCurrent >= 20) ? p5obj.color(255, 209, 42) : p5obj.color(150);

  // 地面
  p5obj.noStroke();
  p5obj.fill(60);
  p5obj.rect(0, 190, 450, 250);

  // 建物を描画
  let buildingHeights: number[] = [
  140, 180, 150, 130, 220
]; // ビルの高さ
  let buildingWidths: number[] = [
  80, 100, 120, 80, 100
]; // ビルの幅
  let buildingColors: p5.Color[] = [p5obj.color(200), p5obj.color(180), p5obj.color(220), p5obj.color(200), p5obj.color(180)]; // ビルの色
  let windowSizes: number[][] = [
  [5, 10], [6, 10], [4, 7], [4, 7], [6, 10]
]; // 窓のサイズを小さく

  // 特別な色のビルのフラグ
let specialBuilding: boolean = secondCurrent % 60 == 0;

  // 通常のビルを先に描画
  for( let i = 0; i < buildingX.length; i++) {
let hIndex: number = i % buildingHeights.length;
let wIndex: number = i % buildingWidths.length;
let wsIndex: number = i % windowSizes.length;
    let bColor = buildingColors[wIndex];
    p5obj.drawBuilding(buildingX[i], groundLevel, buildingWidths[wIndex], buildingHeights[hIndex], bColor);
    p5obj.drawWindows(buildingX[i], groundLevel, buildingWidths[wIndex], buildingHeights[hIndex], windowSizes[wsIndex][0], windowSizes[wsIndex][1], windowColor);
    buildingX[i] += bikeSpeed; // バイクに合わせてスクロール
    if (buildingX[i] > p5obj.width) { // 画面外に出たら再配置
      buildingX[i] = -buildingWidths[wIndex];
    }
  }

  // 特別な色のビルを手前に描画
  if (specialBuilding) {
let i: number = 0; // 一番手前のビルに特別な色を適用
let hIndex: number = i % buildingHeights.length;
let wIndex: number = i % buildingWidths.length;
let wsIndex: number = i % windowSizes.length;
    let bColor = p5obj.color(150, 114, 73); // 特別な色のビル
    p5obj.drawBuilding(buildingX[i], groundLevel, buildingWidths[wIndex], buildingHeights[hIndex], bColor);
    p5obj.drawWindows(buildingX[i], groundLevel, buildingWidths[wIndex], buildingHeights[hIndex], windowSizes[wsIndex][0], windowSizes[wsIndex][1], windowColor);
  }

  // その他の描画...
  // パイプ類
  p5obj.strokeWeight(3);
  p5obj.stroke(0);
  p5obj.line(180, 200, 220, 180);
  p5obj.line(220, 180, 240, 80);
  p5obj.line(200, 100, 260, 190);
  p5obj.line(260, 190, 290, 190);

  p5obj.strokeWeight(15);
  p5obj.line(250, 118, 280, 260);
  p5obj.line(280, 260, 300, 270);
  p5obj.line(310, 200, 270, 210);
  p5obj.line(270, 210, 280, 220);
  p5obj.line(280, 220, 270, 260);

  p5obj.strokeWeight(15);
  p5obj.stroke(60);
  p5obj.line(285, 60, 340, 70);

  // ハンドル
  p5obj.fill(60);
  p5obj.ellipse(310, 20, 8, 15);

  p5obj.strokeWeight(7);
  p5obj.stroke(200);
  p5obj.line(250, 80, 280, 60);

  p5obj.strokeWeight(4);
  p5obj.line(280, 60, 290, 40);
  p5obj.line(290, 40, 300, 30);

  p5obj.stroke(80);
  p5obj.line(250, 80, 260, 76);

  p5obj.stroke(200);
  p5obj.line(280, 60, 320, 70);

  p5obj.noStroke();
  p5obj.fill(30);
  p5obj.circle(280, 60, 20);

  // ボディ
  p5obj.noStroke();
  p5obj.fill(30);
  p5obj.rect(294, 230, 130, 64);

  p5obj.fill(130);
  p5obj.quad(320, 180, 320, 250, 390, 250, 400, 180);

  p5obj.fill(100);
  p5obj.quad(320, 180, 320, 250, 340, 130, 300, 190);

  p5obj.fill(130);
  p5obj.circle(350, 280, 60);

  p5obj.fill(234, 232, 218);
  p5obj.ellipse(123, 250, 160, 120);
  p5obj.triangle(40, 220, 35, 260, 90, 195);

  p5obj.stroke(100);
  p5obj.line(320, 200, 280, 240);
  p5obj.line(280, 240, 290, 290);
  p5obj.line(290, 290, 400, 270);

  // タイヤ
  p5obj.noStroke();
  p5obj.fill(0);
  p5obj.circle(120, 280, 160);
  p5obj.fill(200);
  p5obj.circle(120, 280, 130);
  p5obj.fill(180);
  p5obj.circle(120, 280, 120);

  p5obj.fill(60);
  p5obj.circle(120, 280, 115);
 
  p5obj.fill(200);
  p5obj.circle(120, 280, 50);
  p5obj.fill(210);
  p5obj.circle(120, 280, 40);
let fRadiusS: number = 10;
let fRadiusL: number = 73;

  p5obj.push(); // マトリックスを保存
  p5obj.translate(120, 280);
  p5obj.rotate(p5obj.radians(angle)); // 回転角度を適用
  p5obj.beginShape();
  for( let iDeg = 0; iDeg < 360; iDeg += 15) {
let fSX: number = fRadiusS * p5obj.cos(p5obj.radians(iDeg));
let fSY: number = fRadiusS * p5obj.sin(p5obj.radians(iDeg));
let fLX: number = fRadiusL * p5obj.cos(p5obj.radians(iDeg + 5));
let fLY: number = fRadiusL * p5obj.sin(p5obj.radians(iDeg + 5));

    p5obj.vertex(fSX, fSY);
    p5obj.vertex(fLX, fLY);
  }
  p5obj.endShape(p5obj.CLOSE);
  p5obj.pop(); // マトリックスを復元

  p5obj.fill(20);
  p5obj.quad(200, 100, 194, 138, 220, 130, 220, 90);
}

p5obj.draw = (): void => {  
  // === Time Update ===
  p5obj.updateTimePre();
  
  // hourCurrent = 1;  // 時 を指定して描画を確認したい場合に一時的に有効化

  p5obj.drawBackground();

  // 回転角度を更新
  angle -= 1; // 1度ずつ回転
  if (angle >= 360) {
    angle = 0;
  }

  // 他の描画はそのまま
  p5obj.fill(190);
  p5obj.noStroke();
  p5obj.circle(120, 280, 30);

  // フロントフォーク
  p5obj.stroke(160);
  p5obj.strokeWeight(15);
  p5obj.strokeCap(p5obj.ROUND);
  p5obj.line(120, 280, 230, 120);

  p5obj.strokeWeight(17);
  p5obj.stroke(210);
  p5obj.line(127, 270, 230, 120);

  p5obj.strokeWeight(6);
  p5obj.stroke(90);
  p5obj.line(132, 270, 235, 120);

  p5obj.strokeWeight(3);
  p5obj.stroke(255);
  p5obj.line(125, 270, 230, 118);

  p5obj.noStroke();
  p5obj.fill(60);
  p5obj.arc(155, 230, 25, 25, p5obj.radians(190), p5obj.radians(410), p5obj.CHORD);
  p5obj.arc(195, 170, 25, 25, p5obj.radians(190), p5obj.radians(410), p5obj.CHORD);

  p5obj.fill(190);
  p5obj.noStroke();
  p5obj.circle(120, 280, 30);

  // ヘッド
  p5obj.fill(20);
  p5obj.rect(234, 117, 30, 40);
  p5obj.quad(200, 50, 194, 118, 260, 130, 270, 90);

  p5obj.fill(60);
  p5obj.quad(200, 50, 194, 118, 230, 118, 270, 50);
  p5obj.quad(190, 60, 190, 108, 230, 118, 270, 50);

  p5obj.fill(230);
  p5obj.quad(180, 65, 180, 103, 190, 108, 190, 60);

  p5obj.fill(180);
  p5obj.quad(180, 85, 180, 103, 190, 108, 190, 90);

  p5obj.fill(20);
  p5obj.quad(190, 90, 190, 108, 200, 118, 200, 90);
  p5obj.quad(190, 80, 190, 108, 260, 118, 270, 90);

  p5obj.fill(247, 193, 71);
  p5obj.circle(200, 100, 20);

  p5obj.fill(255, 154, 0);
  p5obj.circle(201, 100, 16);

  p5obj.fill(230);
  p5obj.rect(190, 117, 22, 12);

  p5obj.fill(180);
  p5obj.rect(204, 117, 10, 12);

  // 燃タン
  p5obj.fill(40);
  p5obj.rect(284, 177, 130, 20);

  p5obj.fill(232, 228, 206);
  p5obj.rect(274, 107, 130, 80);
  p5obj.quad(254, 117, 254, 149, 274, 187, 274, 107);
  p5obj.quad(294, 97, 274, 107, 400, 107, 371, 97);

  p5obj.fill(153, 144, 94);
  p5obj.quad(267, 177, 274, 187, 391, 187, 400, 187);
  p5obj.quad(257, 137, 274, 187, 271, 187, 291, 187);

  p5obj.fill(248, 247, 241);
  p5obj.quad(267, 117, 257, 137, 271, 130, 285, 104);
  p5obj.rect(278, 107, 97, 10);

  p5obj.fill(81, 126, 78);
  p5obj.quad(330, 117, 287, 117, 400, 167, 400, 144);
  p5obj.quad(330, 97, 287, 97, 287, 107, 330, 107);

  p5obj.fill(191, 224, 118);
  p5obj.quad(330, 107, 287, 107, 287, 117, 330, 117);

  p5obj.strokeWeight(3);
  p5obj.stroke(0);
  p5obj.fill(255);
  p5obj.rect(284, 150, 80, 24);

  p5obj.fill(0);
  //const myFont = loadFont("Avenir-BlackOblique-48.vlw");
  //p5obj.textFont(myFont);
  p5obj.textSize(21);
  p5obj.text("ZEROS", 290, 170);

//=======================================================================
 




  // 秒が変化した時のアニメーション
  if (secondCurrent != secondPrev) {
    isSecondAnim = 1;  // アニメーション開始
    
    // アニメーション初期化
  }
  if (isSecondAnim == 1) {  // アニメーション中
    // アニメーション中の処理を記述
    isSecondAnim = 0;  // アニメーション終了
  }
  
  // 分が変化した時のアニメーション
  if (minuteCurrent != minutePrev) {
    isMinuteAnim = 1;  // アニメーション開始
    
    // アニメーション初期化
  }
  if (isMinuteAnim == 1) {  // アニメーション中
    // アニメーション中の処理を記述
    isMinuteAnim = 0;  // アニメーション終了
  }
  
  // 時が変化した時のアニメーション
  if (hourCurrent != hourPrev) {
    isHourAnim = 1;  // アニメーションの開始
    
    // アニメーション初期化
  }
  if (isHourAnim == 1) {
    // アニメーション中の処理を記述
    isHourAnim = 0;  // アニメーション終了
  }
  
  // 時間をデバッグ表示（ 提出前に非表示にすること．）
  /*
  p5obj.fill(0);
  p5obj.textSize(20);
  p5obj.text(hourCurrent + ":" + minuteCurrent + ":" + secondCurrent, 10, 20);
  p5obj.text("deltaTimePerSec: " + deltaTimePerSec, 10, 40);
  p5obj.text("deltaTime: " + deltaTime, 10, 60);
  */
  // === Time Update ===
  p5obj.updateTimePost();
}

// === Time Handling ===
let hourPrev: number;
let minutePrev: number;
let secondPrev: number;
let millisCurrent: number;
let millisPrev: number;
let millisPrevSec: number;
// === Time Handling Functions===
p5obj.initTime = (): void =>
{
  hourCurrent = p5obj.hour();
  minuteCurrent = p5obj.minute();
  secondCurrent = p5obj.second();
  millisCurrent = p5obj.millis();
  
  hourPrev = p5obj.hour();
  minutePrev = p5obj.minute();
  secondPrev = p5obj.second();
  millisPrev = p5obj.millis();
  
  millisPrevSec = p5obj.millis();
}
p5obj.updateTimePre = (): void =>
{ 
  if( hourPrev != p5obj.hour() ) hourCurrent = p5obj.hour();
  if( minutePrev != p5obj.minute() ) minuteCurrent = p5obj.minute();
  secondCurrent = p5obj.second();
  millisCurrent = p5obj.millis();
  
  deltaTime = ( millisCurrent - millisPrev ) / 1000;
  
  if ( secondCurrent != secondPrev )
  {
    millisPrevSec = p5obj.millis();
  }
  
  deltaTimePerSec = ( millisCurrent - millisPrevSec ) / 1000;
}
p5obj.updateTimePost = (): void =>
{ 
  hourPrev = hourCurrent;
  minutePrev = minuteCurrent;
  secondPrev = secondCurrent;
  millisPrev = millisCurrent;
}
p5obj.keyPressed = (): void =>
{
  if ( p5obj.key == 's' )
  {
    p5obj.save(pngName);
  }
  else if ( p5obj.key == 'h' )
  {
    hourPrev = -1;
  }
  else if ( p5obj.key == 'm' )
  {
    minutePrev = -1;
  }
}

};

export default sketch;
