// SideBar.tsx

import React, { FC, useState, useEffect } from 'react';
import './Navigator.css';

interface SideBarProps {
  onLinkClicked: (IA: number, itemIndex: number ) => void;
  onReturnClick: () => void;
  onCurLessonClick: () => void;
  isOpen: boolean;
  isReturn: boolean;
  dispList?: SidebarItem[];
  LessonText?: string;
  showToLessonsButton?: boolean;
  showNest?: boolean;
}

interface SidebarItem {
  label: string;
  key: number;
  IA: number;
  nestedList?: SidebarItem[];
}

const SideBar: FC<SideBarProps> = ({ onLinkClicked, onReturnClick, onCurLessonClick, isOpen, isReturn, dispList=null, LessonText, showToLessonsButton=true, showNest=false }) => {
  
  // リンクがクリックされた時の処理
  const handleItemClick = (IA: number, itemIndex: number ) => {
    onLinkClicked(IA,itemIndex);
  };

  // 授業名がクリックされた時の処理
  const handleCurLessonClick =() => {
    onCurLessonClick();
  };

  // 戻るがクリックされた時の処理
  const handleReturnClick = () => {
    onReturnClick();
  };
  
  // アイテムのレンダリング
  const renderListItem = (item: SidebarItem, index: number) => {
    return (
      <li key={item.key} style={{ backgroundColor: (item.label.startsWith('課題') || item.label.startsWith('演習')) ? '#f6f6f5' : 'transparent' }}>
        <button onClick={() => handleItemClick(item.IA, index)}>{item.label}</button>
        {showNest && item.nestedList && (
          <ul>
            {item.nestedList.map((nestedItem, nestedIndex) => (
              <li key={nestedItem.key}>
                <button onClick={() => handleItemClick(nestedItem.IA,nestedIndex)}>{nestedItem.label}</button>
              </li>
            ))}
          </ul>
        )}
      </li>
    );
  };

  return (
    <div className={`sidebar ${isOpen ? 'open' : ''}`}>

      {/* 戻るボタン */}
      {showToLessonsButton && (
        <button className="button-return" onClick={handleReturnClick}>
          {isReturn ? `授業一覧へ` : `演習一覧へ戻る`}
        </button>
      )}

      {/* 授業名 */}
            {isReturn && (
        <button className="Lesson-button" onClick={handleCurLessonClick}>
          {LessonText}
        </button>
      )}

      <div className="sidebar-list">
        <ul>
          {dispList ? (
            dispList.map(renderListItem)
          ) : (
            <li>No items to display</li>
          )}
        </ul>
      </div>
    </div>
  );
};

export default SideBar;