const sketch = (p5obj:any) => {
    p5obj.setup = () => {
p5obj.createCanvas(500, 500);
p5obj.translate(p5obj.width/2.0, p5obj.height/2.0);  //蠎ｧ讓吶ｒ荳ｭ蠢・↓遘ｻ蜍・
p5obj.blendMode( p5obj.SUBTRACT );

var n = 150000;               //隧ｦ陦悟屓謨ｰ
var p = p5obj.width/5.0;       //x縺ｮ諡｡螟ｧ邇・
var q = p5obj.height/5.0;      //y縺ｮ諡｡螟ｧ邇・
var X = 0;                      //x縺ｮ蛻晄悄蛟､
var Y = 0;                      //y縺ｮ蛻晄悄蛟､
var x, y;

for (var i=0; i<n/3; i++) {    //蜈ｨ隧ｦ陦後・1/3繧定ｵ､轤ｹ縺ｧ繝励Ο繝・ヨ
  x = p5obj.sin(Y)+p5obj.cos(3*X);
  y = p5obj.sin(X)+p5obj.cos(Y);
  X = x;
  Y = y;
  p5obj.stroke(255, 0, 0);
  p5obj.point(x*p, y*q);
}

for (var i=0; i<2*n/3; i++) {   //縺昴・荳翫°繧・/3繧堤ｷ醍せ縺ｧ貂帷ｮ・
  x = p5obj.sin(Y)+p5obj.cos(3*X);
  y = p5obj.sin(X)+p5obj.cos(Y);
  X = x;
  Y = y;
  p5obj.stroke(0, 255, 0);
  p5obj.point(x*p, y*q);
}

for (var i=0; i<n; i++) {            //縺輔ｉ縺ｫ蜈ｨ驛ｨ繧帝搨轤ｹ縺ｧ貂帷ｮ・
  x = p5obj.sin(Y)+p5obj.cos(3*X);
  y = p5obj.sin(X)+p5obj.cos(Y);
  X = x;
  Y = y;
  p5obj.stroke(0, 0, 255);
  p5obj.point(x*p, y*q);
}

  };
};

export default sketch;
