p5obj.Dejoukun = (iX: number, iY: number, iDeg: number): void =>
{
  p5obj.fill(148, 93, 216);

  p5obj.push();

  p5obj.translate( iX, iY );
  p5obj.rotate( p5obj.radians( iDeg ) );

  p5obj.noStroke();  // fuchi nashi

  // finger
  p5obj.fill( fR, fG, fB );
  p5obj.ellipse( 100, -49, 104, 136 );

  // finger mask
  p5obj.fill( 15, 31, 58 );
  p5obj.ellipse( 190, -70, 200, 200 );

  // daen
  p5obj.fill( fR, fG, fB );
  p5obj.ellipse( 0, 30, 260, 200 );

  // mouth mask
  p5obj.fill( 15, 31, 58);
  p5obj.ellipse( 0, 4, 116, 186 );

  // ue daen mask
  p5obj.fill( fR, fG, fB );
  p5obj.ellipse( 0, -4, 200, 134 );

  // daen mask
  p5obj.fill( 15, 31, 58);
  p5obj.ellipse( 0, 4, 90, 60 );

  p5obj.pop();
}



//ルーン文字描画の関数。処理が重すぎたため、３つの関数に分けて一周描画している。ルーン文字は《dejoukun》と書いている
p5obj.dejoukun1 = (iX: number, iY: number): void =>
{
  p5obj.strokeWeight(6.5);
  p5obj.push();
  p5obj.d(iX, iY);

  p5obj.rotate(p5obj.radians(15));
  p5obj.translate(80, -85);
  p5obj.e(iX, iY);

  p5obj.rotate(p5obj.radians(15));
  p5obj.translate(70, -85);
  p5obj.j(iX, iY);

  p5obj.rotate(p5obj.radians(15));
  p5obj.translate(70, -85);
  p5obj.o(iX, iY);

  p5obj.rotate(p5obj.radians(15));
  p5obj.translate(70, -85);
  p5obj.u(p5obj.float(iX), p5obj.float(iY));

  p5obj.rotate(p5obj.radians(15));
  p5obj.translate(70, -80);
  p5obj.k(p5obj.float(iX), p5obj.float(iY));

  p5obj.rotate(p5obj.radians(15));
  p5obj.translate(60, -85);
  p5obj.u(iX, iY);

  p5obj.rotate(p5obj.radians(15));
  p5obj.translate(60, -85);
  p5obj.n(iX, iY);

  p5obj.rotate(p5obj.radians(15));
  p5obj.translate(60, -85);
  p5obj.n(iX, iY);
  p5obj.pop();
}


