///////ルーンもじフォント//////////
p5obj.d = (iX: number, iY: number): void =>
{
  p5obj.beginShape();
  p5obj.vertex(iX, iY);
  p5obj.vertex(iX+30, iY+30 );
  p5obj.vertex(iX+30, iY);
  p5obj.vertex(iX, iY+30);
  p5obj.vertex(iX, iY);
  p5obj.endShape();
}

p5obj.e = (iX: number, iY: number): void =>
{
  p5obj.beginShape();
  p5obj.vertex(iX, iY+30);
  p5obj.vertex(iX, iY);
  p5obj.vertex(iX+15, iY+10);
  p5obj.vertex(iX+30, iY);
  p5obj.vertex(iX+30, iY+30);
  p5obj.endShape();
}

p5obj.j = (iX: number, iY: number): void =>
{
  p5obj.beginShape();
  p5obj.vertex(iX+15, iY-5);
  p5obj.vertex(iX+15, iY+30);
  p5obj.endShape();

  p5obj.beginShape();
  p5obj.vertex(iX+15, iY);
  p5obj.vertex(iX+5, iY+15);
  p5obj.vertex(iX+15, iY+25);
  p5obj.vertex(iX+25, iY+15);
  p5obj.vertex(iX+15, iY);
  p5obj.endShape();
}

p5obj.o = (iX: number, iY: number): void =>
{
  p5obj.beginShape();
  p5obj.vertex(iX, iY+25);
  p5obj.vertex(iX+25, iY+10);
  p5obj.vertex(iX+12.5, iY);
  p5obj.vertex(iX, iY+10);
  p5obj.vertex(iX+25, iY+25);
  p5obj.endShape();
}

p5obj.u = (fX: number, fY: number): void =>
{
  p5obj.beginShape();
  p5obj.vertex(fX, fY+30);
  p5obj.vertex(fX, fY);
  p5obj.arc(fX, fY+30, 40, 60, p5obj.radians(0-90), p5obj.radians(90-90));

  p5obj.endShape();
}

p5obj.k = (fX: number, fY: number): void =>
{
  p5obj.beginShape();
  p5obj.vertex(fX, fY+30);
  p5obj.vertex(fX, fY);
  p5obj.arc(fX, fY, 40, 30, p5obj.radians(0), p5obj.radians(90));

  p5obj.endShape();
}

p5obj.n = (iX: number, iY: number): void =>
{
  p5obj.beginShape();
  p5obj.vertex(iX+10, iY);
  p5obj.vertex(iX+10, iY+30);
  p5obj.endShape();

  p5obj.beginShape();
  p5obj.vertex(iX, iY+5);
  p5obj.vertex(iX+20, iY+20);
  p5obj.endShape();
}

p5obj.Shokan = (): void =>
{
  if ( isShokanFrame > 385) //光が大きくなりながら、魔法陣の中央より上昇
  {
    p5obj.blendMode(p5obj.ADD);
    p5obj.fill(148,93,216);
    p5obj.circle(300,0-(350-isShokanFrame)*3,(500-isShokanFrame));
     isShokanFrame --;
    p5obj.blendMode(p5obj.BLEND);
  }
   else if ( isShokanFrame > 200) //光が拡大
  {
    p5obj.blendMode(p5obj.ADD);
     p5obj.fill(148,93,216);
    p5obj.circle(300,-300-(0-400),(500-isShokanFrame));
     isShokanFrame --;
    p5obj.blendMode(p5obj.BLEND);
  }
  else if( isShokanFrame > 40) //デ情くんが召喚される。少しずつ色が暗くなってフェードアウト
  {

    p5obj.push();
    p5obj.scale(0.5);
   p5obj.DejoukunShokan(600, 180,0,(148-(200-isShokanFrame)),(93-(200-isShokanFrame)),(216-(200-isShokanFrame)));
    isShokanFrame --;
    p5obj.pop();
  }
}


p5obj.DejoukunShokan = (iX: number, iY: number, iDeg: number, iR: number, iG: number, iB: number): void =>
{
  p5obj.fill(148, 93, 216);

  p5obj.push();

  p5obj.translate( iX, iY );
  p5obj.rotate( p5obj.radians( iDeg ) );

  p5obj.noStroke();  // fuchi nashi

  // finger
  p5obj.fill( iR,iG,iB);
  p5obj.ellipse( 100, -49, 104, 136 );

  // finger mask
  p5obj.fill( 10, 16, 43 );
  p5obj.ellipse( 190, -70, 200, 200 );

  // daen
  p5obj.fill( iR,iG,iB );
  p5obj.ellipse( 0, 30, 260, 200 );

  // mouth mask
  p5obj.fill( 10, 16, 43);
  p5obj.ellipse( 0, 4, 116, 186 );

  // ue daen mask
  p5obj.fill( iR,iG,iB );
  p5obj.ellipse( 0, -4, 200, 134 );

  // daen mask
  p5obj.fill( 10, 16, 43);
  p5obj.ellipse( 0, 4, 90, 60 );

  p5obj.pop();
}

// === Time Handling ===
let hourPrev: number;
let minutePrev: number;
let secondPrev: number;
let millisCurrent: number;
let millisPrev: number;
let millisPrevSec: number;
// === Time Handling Functions===
p5obj.initTime = (): void =>
{
  hourCurrent = p5obj.hour();
  minuteCurrent = p5obj.minute();
  secondCurrent = p5obj.second();
  millisCurrent = p5obj.millis();
  
  hourPrev = p5obj.hour();
  minutePrev = p5obj.minute();
  secondPrev = p5obj.second();
  millisPrev = p5obj.millis();
  
  millisPrevSec = p5obj.millis();
}
p5obj.updateTimePre = (): void =>
{ 
  if( hourPrev != p5obj.hour() ) hourCurrent = p5obj.hour();
  if( minutePrev != p5obj.minute() ) minuteCurrent = p5obj.minute();
  secondCurrent = p5obj.second();
  millisCurrent = p5obj.millis();
  
  deltaTime = ( millisCurrent - millisPrev ) / 1000;
  
  if ( secondCurrent != secondPrev )
  {
    millisPrevSec = p5obj.millis();
  }
  
  deltaTimePerSec = ( millisCurrent - millisPrevSec ) / 1000;
}
p5obj.updateTimePost = (): void =>
{ 
  hourPrev = hourCurrent;
  minutePrev = minuteCurrent;
  secondPrev = secondCurrent;
  millisPrev = millisCurrent;
}
p5obj.keyPressed = (): void =>
{
  if ( p5obj.key == 's' )
  {
    p5obj.save(pngName);
  }
  else if ( p5obj.key == 'h' )
  {
    ih ++;
    if(ih>=12)
    {
      ih=0;
      isShokanFrame=500;
    }
  }
  else if ( p5obj.key == 'm' )
  {
    minutePrev = -1;
  }
}

