const sketch = (p:any) => {
    p.setup = () => {
p.createCanvas(500, 500);      // Window Size
p.colorMode(p.RGB, 1.0); // RGB(0.0~1.0)
var fR, fG, fB;      // Window RGB
for (var iX=0; iX<p.width; iX++)
{
  for (var iY=0; iY<p.height; iY++)
  {
    /* Example */
    fR = p.sin((p.pow(iY-250, 2)/iX+p.pow(iY-250, 2)/iX)/40);
    fG = p.tan(iX/5.0)*p.sin(iY/9.2)*p.cos(iX/1.2);
    fB = p.cos((p.pow(iY-5.5, 10)/p.pow(iY-0.5, 10)*p.pow(iX*5.5, 1.5))/3.0);

    // draw pixel
    p.stroke(fR, fG, fB);
    p.point(iX, iY);
  }
}

  };
};

export default sketch;
