const sketch = (p5obj:any) => {
p5obj.setup = () => 
{
  p5obj.createCanvas(1000, 1000);
  p5obj.colorMode(p5obj.RGB, 100, 100, 100, 100);
  p5obj.background( 0, 0, 0 );
}
p5obj.draw = () => 
{  
  p5obj.rotate( p5obj.radians( -30 ) );//座標移動
  p5obj.translate(200,-600);
  for( let umoux: number = 0; umoux < 8; umoux++ )//繰り返し
  {
     for( let umouy: number = 0; umouy<15; umouy++ )
     {
    p5obj.push();
    p5obj.translate(-umoux*p5obj.random(250,320),-umouy*p5obj.random(250,330));
    feather(500,0,550,90);
    p5obj.pop();
      }
  }
}
const feather = (fbeginx: number, fbeginy: number, fline: number, degree: number) => {
   p5obj.stroke(p5obj.random(0, 10), p5obj.random(30, 65), p5obj.random(20, 65),20);//羽の色
    if (fline<10)//線分の長さ指定による先端の色変更
  {
    p5obj.stroke(80+fline/60,70+fline/60,20-30/fline,50/fline);
  }
  let fEndX: number = fbeginx + 0.3*fline * p5obj.cos( p5obj.radians( degree ) );//羽幅
  let fEndY: number = fbeginy + fline * p5obj.sin( p5obj.radians( degree ) );//羽高さ
  p5obj.line( fbeginx, fbeginy, fEndX, fEndY );//羽描画
  if (fline>10)
  {
    feather(fEndX,fEndY,fline*0.8,degree+5);
    feather(fEndX,fEndY,fline*0.8,degree-5);
  }
}

};

export default sketch;
