const sketch = (p5obj:any) => {
// === アニメーション用変数/定数 ===
// 背景の星
let iStarsProp: number[][] = Array.from({ length: 20 }, () => Array(5).fill(0));

// 花火
let fHanabiHourProp:number[][] = Array.from({ length: 60 }, () => Array(6).fill(0));
let fHanabiSecondProp:number[][] = Array.from({ length: 60 }, () => Array(7).fill(0));  // タイマー内蔵

// 花火タイマー
let fHanabiHourTimer: number = 0;

// === Time Handling ===

let hourCurrent: number = 0;
       // 現在の時（0~23）
let minuteCurrent: number = 0;
     // 現在の分（0~59）
let secondCurrent: number = 0;
     // 現在の秒（0~59）
let deltaTime: number = 0;
       // 前フレームからの経過時間（秒,0~1）
let deltaTimePerSec: number = 0;
 // 前回の秒が切り替わってからの経過時間（秒,0~1）
let isHourAnim: number = 0;    // アニメーションフラグ（1:アニメーション中）
let isMinuteAnim: number = 0;
let isSecondAnim: number = 0;

let hourPrev: number = 0;

let minutePrev: number = 0;

let secondPrev: number = 0;

let millisCurrent: number = 0;

let millisPrev: number = 0;

let millisPrevSec: number = 0;


 
p5obj.setup = () => 
{
  p5obj.createCanvas( 400, 400 );
  p5obj.frameRate( 30 );  // フレームレートの指定
  
  // === Time Init ===
  initTime();
  
  // 星配列の初期化
  for( let iStar: number = 0; iStar < iStarsProp.length; iStar++ ) 
  {
    iStarsProp[iStar][0] = p5obj.random( p5obj.width );    // X座標
    iStarsProp[iStar][1] = p5obj.random( p5obj.height );   // Y座標
    iStarsProp[iStar][2] = p5obj.random( 4, 8 );     // 大きさ
    iStarsProp[iStar][3] = p5obj.random( 255 );      // 明るさ
    iStarsProp[iStar][4] = 1;                  // 1:明るくなる．-1:暗くなる．
  }
}

p5obj.draw = () => 
{  
  // === Time Update ===
  updateTimePre();
  
  //hourCurrent = 23;  // 時 を指定して描画を確認したい場合に一時的に有効化
  
  // === 画面のクリア ===
  
  // 画面をクリア
  p5obj.fill( 0  );
  p5obj.noStroke();
  p5obj.rect( 0, 0, p5obj.width, p5obj.height );

  // 既定の描画カラーに戻す．
  p5obj.fill( 255 );
  p5obj.stroke( 0 );
  
  // === アニメーションを記述 ===
  p5obj.colorMode(p5obj.HSB, 360, 1, 1, 1 );
  
  // 背景の星
  for( let iStar: number = 0; iStar < iStarsProp.length; iStar++ )
  {
    p5obj.fill( iStarsProp[iStar][3] );
    p5obj.circle( iStarsProp[iStar][0], iStarsProp[iStar][1], iStarsProp[iStar][2] );
  }
  // 明るさ更新
  for( let iStar: number = 0; iStar < iStarsProp.length; iStar++ )
  {
    iStarsProp[iStar][3] += iStarsProp[iStar][4] * 255 / 60.0;
    
    // 明るくなるか暗くなるか切り替える．
    if( iStarsProp[iStar][3] < 0 || iStarsProp[iStar][3] > 255 )
    {
      iStarsProp[iStar][4] *= -1;
    }
  }
  
  // 秒が変化した時のアニメーション
  if ( secondCurrent != secondPrev )
  {
    isSecondAnim = 1;  // アニメーション開始
    
    // アニメーション初期化
    // 新しい花火の準備，配列の要素を１つだけ初期化
    fHanabiSecondProp[secondCurrent][0] = 20 + secondCurrent * 6;// X座標
    fHanabiSecondProp[secondCurrent][1] = p5obj.random( 400, 420 );     // Y座標
    fHanabiSecondProp[secondCurrent][2] = p5obj.random( 2, 4 );         // 大きさ
    fHanabiSecondProp[secondCurrent][3] = p5obj.random( 40, 300 );      // 最大の大きさ
    fHanabiSecondProp[secondCurrent][4] = p5obj.random( 255 );          // 色相
    fHanabiSecondProp[secondCurrent][5] = 0;                      // 1:明るくなる．-1:暗くなる．
    fHanabiSecondProp[secondCurrent][6] = 0;                      // タイマーリセット
  }
  if ( isSecondAnim == 1 )  // アニメーション中
  {
    // アニメーション中の処理を記述
    // 全秒花火の更新と描画
    for( let iHanabi: number = 0; iHanabi < fHanabiSecondProp.length; iHanabi++ ) 
    {      
      // 花火の更新
      if( fHanabiSecondProp[iHanabi][6] < 4 )
      {
        // 上昇中
        fHanabiSecondProp[iHanabi][1] -= p5obj.random( 5, 50 + 1.8 * minuteCurrent ) * deltaTime;    // 上昇
        fHanabiSecondProp[iHanabi][2] += p5obj.random( 0, 1 ) * deltaTime;     // 大きさ
        fHanabiSecondProp[iHanabi][5] += p5obj.random( 0.1, 0.5 ) * deltaTime; // 明るさ
      }
      else if( fHanabiSecondProp[iHanabi][6] < 10 )
      {
        // パッと開く
        // 最大の大きさとの差があるほど早く大きくなる
        fHanabiSecondProp[iHanabi][2] += ( fHanabiSecondProp[iHanabi][3] - fHanabiSecondProp[iHanabi][2] ) * deltaTime;
        fHanabiSecondProp[iHanabi][5] -= p5obj.random( 0.5, 1 ) * deltaTime;  // 明るさ
      }
      
      // 花火タイマー更新
      fHanabiSecondProp[iHanabi][6] += deltaTime;
      
      // 花火の描画（10秒間）
      if( fHanabiSecondProp[iHanabi][6] < 10 )
      {
        p5obj.noFill();
        p5obj.stroke( fHanabiSecondProp[iHanabi][4], 0.3, fHanabiSecondProp[iHanabi][5], 0.9 );
        p5obj.strokeWeight( p5obj.random( 1, 2 ) );
        p5obj.circle( fHanabiSecondProp[iHanabi][0], fHanabiSecondProp[iHanabi][1], fHanabiSecondProp[iHanabi][2] );
      }
    }
  }
  
  
  // 分が変化した時のアニメーション
  if ( minuteCurrent != minutePrev )
  {
    isMinuteAnim = 1;  // アニメーション開始
    
    // アニメーション初期化
    
    
  }
  if( isMinuteAnim == 1 )  // アニメーション中
  {
    // アニメーション中の処理を記述
    
    
    
    isMinuteAnim = 0;  // アニメーション終了
  }
  
  
  // 時が変化した時のアニメーション
  if ( hourCurrent != hourPrev )
  {
    isHourAnim = 1;  // アニメーションの開始
    
    // アニメーション初期化
    // 花火配列の初期化
    for( let iHanabi: number = 0; iHanabi < fHanabiHourProp.length; iHanabi++ ) 
    {
      fHanabiHourProp[iHanabi][0] = p5obj.random( 50, 350 );    // X座標
      fHanabiHourProp[iHanabi][1] = p5obj.random( 400, 420 );   // Y座標
      fHanabiHourProp[iHanabi][2] = p5obj.random( 2, 4 );       // 大きさ
      fHanabiHourProp[iHanabi][3] = p5obj.random( 40, 300 );    // 最大の大きさ
      fHanabiHourProp[iHanabi][4] = p5obj.random( 255 );        // 色相
      fHanabiHourProp[iHanabi][5] = 0;                    // 1:明るくなる．-1:暗くなる．
    }
    
    fHanabiHourTimer = 0;  // タイマーリセット
  }
  if( isHourAnim == 1 )
  {
    // アニメーション中の処理を記述
    // 打ち上げる時の花火の数
    let iHanabiHourNum: number = 14 + hourCurrent * 2;  // 14~60
    
    if( fHanabiHourTimer < 4 )
    {
      // 上昇中
      for( let iHanabi: number = 0; iHanabi < iHanabiHourNum; iHanabi++ ) 
      {
        fHanabiHourProp[iHanabi][1] -= p5obj.random( 5, 100 ) * deltaTime;    // 上昇
        fHanabiHourProp[iHanabi][2] += p5obj.random( 0, 1 ) * deltaTime;     // 大きさ
        fHanabiHourProp[iHanabi][5] += p5obj.random( 0.1, 0.5 ) * deltaTime; // 明るさ
      }    
    }
    else if( fHanabiHourTimer < 10 )
    {
      // パッと開く
      for( let iHanabi: number = 0; iHanabi < iHanabiHourNum; iHanabi++ ) 
      {
        // 最大の大きさとの差があるほど早く大きくなる
        fHanabiHourProp[iHanabi][2] += ( fHanabiHourProp[iHanabi][3] - fHanabiHourProp[iHanabi][2] ) * deltaTime;
        fHanabiHourProp[iHanabi][5] -= p5obj.random( 0.5, 1 ) * deltaTime;         // 明るさ
      }    
    }
    else
    {
      isHourAnim = 0;  // アニメーション終了
    }
    
    fHanabiHourTimer += deltaTime;  // タイマーを進める．
    
    // 花火の描画
    for( let iHanabi: number = 0; iHanabi < iHanabiHourNum; iHanabi++ ) 
    {
      p5obj.noFill();
      p5obj.stroke( fHanabiHourProp[iHanabi][4], 0.3, fHanabiHourProp[iHanabi][5], 0.9 );
      p5obj.strokeWeight( p5obj.random( 1, 2 ) );
      p5obj.circle( fHanabiHourProp[iHanabi][0], fHanabiHourProp[iHanabi][1], fHanabiHourProp[iHanabi][2] );
    }
  }
  
  
  // === Time Update ===
  updateTimePost();
}
const initTime = () => {
  hourCurrent = p5obj.hour();
  minuteCurrent = p5obj.minute();
  secondCurrent = p5obj.second();
  millisCurrent = p5obj.millis();
  
  hourPrev = p5obj.hour();
  minutePrev = p5obj.minute();
  secondPrev = p5obj.second();
  millisPrev = p5obj.millis();
  
  millisPrevSec = p5obj.millis();
}
const updateTimePre = () => { 
  if( hourPrev != p5obj.hour() ) hourCurrent = p5obj.hour();
  if( minutePrev != p5obj.minute() ) minuteCurrent = p5obj.minute();
  secondCurrent = p5obj.second();
  millisCurrent = p5obj.millis();
  
  deltaTime = ( millisCurrent - millisPrev ) / 1000;
  
  if ( secondCurrent != secondPrev )
  {
    millisPrevSec = p5obj.millis();
  }
  
  deltaTimePerSec = ( millisCurrent - millisPrevSec ) / 1000;
}
const updateTimePost = () => { 
  hourPrev = hourCurrent;
  minutePrev = minuteCurrent;
  secondPrev = secondCurrent;
  millisPrev = millisCurrent;
}
};

export default sketch;
