const sketch = (p5obj:any) => {
/**************************************************************
 電子軌道や超弦理論とかをイメージしながら作りました。
 定常波を円形に変えたもので、波の数を見て時間を読むことができます。
 左から時・分・秒、内側の波は時間の一桁目・外側の波は二桁目を表しています。
 コードは全部自分が作成したので、雑になっていると思います。
 **************************************************************/
/**
 デバッグ機能
 'S'キー：png出力
 'H'キー：時が変わったときのアニメーション再生
 'M'キー：分が変わったときのアニメーション再生
 */
// === 'S'キーを押した時の出力画像名 ===
//  "K3_[クラス][番号]_[苗字].png"
let pngName: String = "K3_A12_fukushima.png";

// === アニメーション用変数/定数 ===



// === Time Handling ===
let hourCurrent: number;       // 現在の時（0~23）
let minuteCurrent: number;     // 現在の分（0~59）
let secondCurrent: number;     // 現在の秒（0~59）
let deltaTime: number;       // 前フレームからの経過時間（秒,0~1）
let deltaTimePerSec: number; // 前回の秒が切り替わってからの経過時間（秒,0~1）
let isHourAnim: number = 0;    // アニメーションフラグ（1:アニメーション中）
let isMinuteAnim: number = 0;
let isSecondAnim: number = 0;
let ms: number;  //deltaTimePerSecの変数名が長すぎて短縮 (0~1000)
let hours: number[] = new Array(800);

p5obj.setup = (): void =>
{
  p5obj.createCanvas( 1000, 500 );
  p5obj.frameRate( 30 );  // フレームレートの指定
  p5obj.colorMode(p5obj.HSB, 360, 100, 100, 255);

  // === Time Init ===
  p5obj.initTime();
}

p5obj.draw = (): void =>
{
  // === Time Update ===
  p5obj.updateTimePre();

  p5obj.fill(0, 220);
  p5obj.rect(-10, -10, p5obj.width+20, p5obj.height+20);
  p5obj.noFill();
  p5obj.strokeWeight(3);
  
  // === アニメーションを記述 ===

  //tens digit of second
  p5obj.push();
  p5obj.translate(800, 250);
  p5obj.shearY(-p5obj.sin(2*p5obj.radians(ms*360/1000))/50);  //振動数が0の時にも若干動くようにする
  p5obj.scale(0.5, 0.5);
  p5obj.rotate(p5obj.radians(p5obj.millis()*20/1000));  // かける数字 = degree per sec
  p5obj.circularWave(25, (p5obj.second() - p5obj.second()%10) / 10, 250);
  p5obj.pop();

  //ones digit of second
  p5obj.push();
  p5obj.translate(800, 250);
  p5obj.shearY(p5obj.sin(3*p5obj.radians(ms*360/1000))/100);
  p5obj.scale(0.5, 0.5);
  p5obj.rotate(p5obj.radians(p5obj.millis()*40/1000));  //30degrees per sec
  p5obj.circularWave(25, p5obj.second()%10, 150);
  p5obj.pop();

  //tens digit of minute
  p5obj.push();
  p5obj.translate(500, 250);
  p5obj.shearY(-p5obj.sin(2*p5obj.radians(ms*360/1000))/50);
  p5obj.scale(0.5, 0.5);
  p5obj.rotate(p5obj.radians(p5obj.millis()*10/1000));  //10degrees per sec
  p5obj.circularWave(25, (p5obj.minute() - p5obj.minute()%10) / 10, 250);
  p5obj.pop();

  //ones digit of minute
  p5obj.push();
  p5obj.translate(500, 250);
  p5obj.shearY(p5obj.sin(3*p5obj.radians(ms*360/1000))/100);
  p5obj.scale(0.5, 0.5);
  p5obj.rotate(p5obj.radians(p5obj.millis()*20/1000));  //15degrees per sec
  p5obj.circularWave(25, p5obj.minute()%10, 150);
  p5obj.pop();

  //tens digit of hour
  p5obj.push();
  p5obj.translate(200, 250);
  p5obj.shearY(-p5obj.sin(1*p5obj.radians(ms*360/1000))/50);
  p5obj.scale(0.5, 0.5);
  p5obj.rotate(p5obj.radians(p5obj.millis()*5/1000));  //5degrees per sec
  p5obj.circularWave(25, (p5obj.hour() - p5obj.hour()%10) / 10, 250);
  p5obj.pop();

  //ones digit of hour
  p5obj.push();
  p5obj.translate(200, 250);
  p5obj.shearY(p5obj.sin(2*p5obj.radians(ms*360/1000))/100);
  p5obj.scale(0.5, 0.5);
  p5obj.rotate(p5obj.radians(p5obj.millis()*10/1000));  //10degrees per sec
  p5obj.circularWave(25, p5obj.hour()%10, 150);
  p5obj.pop();

  // === Time Update ===
  p5obj.updateTimePost();
}



//CUSTOM FUNCTIONS

p5obj.circularWave = (a: number, b: number, r: number): void => {  //a: 振幅 b: 振動数 r: 半径
  p5obj.push();
  p5obj.scale(1.9, 1.9);
  for( let s = 20; s >= 0; s--) {  //同心円を描く
    p5obj.stroke(210, 40+p5obj.sqrt(s)*30, 100-s*3, 255 - p5obj.sqrt(s)*57.0);  //外側を青く、内側を白く
    //p5obj.stroke(210, 40+p5obj.sqrt(s)*30, 100-s*3, 0.5);  //外側を青く、内側を白く
    p5obj.scale(0.97, 0.97);
let c: number = a * p5obj.sin(p5obj.radians(ms - 500) * 180 / (500));  //波が揺れるようにする(-1 < c < +1)

    p5obj.beginShape();
    for( let i = 0; i < 360; i++) {
let p: number = c * p5obj.sin(p5obj.radians(i*b)) + r;  //波の数＝時間
      p5obj.vertex(p5obj.cos(p5obj.radians(i))*p, p5obj.sin(p5obj.radians(i))*p);  //サイン波を円形に変換
    }
    p5obj.endShape(p5obj.CLOSE);
  }
  p5obj.pop();
}
/*
  線形の定常波も入れようと思いましたが
 原因のわからないバグがあって諦めました
 
 p5obj.linearWave = (a: number): void => {  //a: 振幅 b: 振動数
let b: number = (p5obj.hour() - p5obj.hour()%10) / 10;  //tens digit
let c: number = a * p5obj.sin(p5obj.radians((p5obj.second() * 1000 + ms) - 500) * 180 / 2 / 500);
let b1: number = p5obj.hour()%10 + 5;  //ones digit
let c1: number = 15 * p5obj.sin(p5obj.radians((p5obj.second() * 1000 + ms) - 500) * 180 / 500);
 
 p5obj.beginShape();
 for( let i = 0; i < 800; i++) {
let p: number = c * p5obj.sin(p5obj.radians(i*b*180/800));
 hours[i] = p;
 p5obj.vertex(i, hours[i] - hours[200]);
 }
 p5obj.endShape();
 
 p5obj.beginShape();
 for( let i = 0; i < 800; i++) {
let p: number = c1 * p5obj.sin(p5obj.radians(i*b1*180/800));
 p5obj.vertex(i, p + 2 * hours[200]);
 }
 p5obj.endShape();
 
 }
 */
 
 // === Time Handling ===
let hourPrev: number;
let minutePrev: number;
let secondPrev: number;
let millisCurrent: number;
let millisPrev: number;
let millisPrevSec: number;
// === Time Handling Functions===
p5obj.initTime = (): void =>
{
  hourCurrent = p5obj.hour();
  minuteCurrent = p5obj.minute();
  secondCurrent = p5obj.second();
  millisCurrent = p5obj.millis();
  
  hourPrev = p5obj.hour();
  minutePrev = p5obj.minute();
  secondPrev = p5obj.second();
  millisPrev = p5obj.millis();
  
  millisPrevSec = p5obj.millis();
}
p5obj.updateTimePre = (): void =>
{ 
  if( hourPrev != p5obj.hour() ) hourCurrent = p5obj.hour();
  if( minutePrev != p5obj.minute() ) minuteCurrent = p5obj.minute();
  secondCurrent = p5obj.second();
  millisCurrent = p5obj.millis();
  
  deltaTime = ( millisCurrent - millisPrev ) / 1000;
  
  if ( secondCurrent != secondPrev )
  {
    millisPrevSec = p5obj.millis();
  }
  
  deltaTimePerSec = ( millisCurrent - millisPrevSec ) / 1000;
  ms = millisCurrent - millisPrevSec;
}
p5obj.updateTimePost = (): void =>
{ 
  hourPrev = hourCurrent;
  minutePrev = minuteCurrent;
  secondPrev = secondCurrent;
  millisPrev = millisCurrent;
}
p5obj.keyPressed = (): void =>
{
  if ( p5obj.key == 's' )
  {
    p5obj.save(pngName);
  }
  else if ( p5obj.key == 'h' )
  {
    hourPrev = -1;
  }
  else if ( p5obj.key == 'm' )
  {
    minutePrev = -1;
  }
}

};

export default sketch;
