const sketch = (p:any) => {
    p.setup = () => {
p.createCanvas(500, 500);      // Window Size
p.colorMode(p.RGB, 1.0); // RGB(0.0~1.0)
var fR, fG, fB;      // Window RGB
for (var iX=0; iX<p.width; iX++)
{
  for (var iY=0; iY<p.height; iY++)
  {
    fR=p.tan((p.pow(iX-250, 10)+p.pow(iY-250, 2))/iY+100);
    fG=p.cos((p.pow(iX-100, 2)+p.pow(iY-200, 2))/10);
    fB=p.tan((p.pow(iX-100, 10)+p.pow(iY-250, 2))/150/iY+p.pow(iY-100, 2)/iY);

    // draw pixel
    p.stroke(fR, fG, fB);
    p.point(iX, iY);
  }
}

  };
};

export default sketch;
