const sketch = (p5obj:any) => {
p5obj.setup = () => 
{
  p5obj.createCanvas(1000, 1000);
  p5obj.colorMode(p5obj.HSB, 360, 1.0, 1.0, 1.0);
  p5obj.background(185, 0.6, 0.8); //Blue
  
  for(let i: number = 1; i < 22; i++) //Sky
  {
    p5obj.noStroke();
    p5obj.fill(45, 0.1, 1.0, 0.15); //Light Brown gradation
    p5obj.rect(0, 0, p5obj.width, 40*i);
  }
  
  p5obj.noStroke();
  p5obj.fill(114, 0.5, 0.7); //Green
  p5obj.ellipse(p5obj.width/2, 1040, 1200, 400); //Hill
  
  strangetree(p5obj.width/2, 850, 200, 450, 10, 250);
}

const strangetree = (fX: number, fBeginY: number, fverL: number, fholL: number, fsW: number, fW: number) => {
  //Stroke setting
  p5obj.stroke(31, 0.2, 0.6); //Brown
  p5obj.strokeWeight(fsW);
  
  // Vertical line
  let fEndY: number = fBeginY - fverL; //Calculate upper Y
  p5obj.line(fX, fBeginY, fX, fEndY);
  
  // Horizontal line
  let fLeft: number = fX - fholL/2; //Calculate left X
  let fRight: number = fX + fholL/2; //Calculate rightX
  p5obj.strokeWeight(fsW * 0.9);
  p5obj.line(fLeft, fEndY, fRight, fEndY);
  
  let fRR: number = (p5obj.random(9));
  let fRL: number = (p5obj.random(9));
  let fNextEndY: number = fEndY - fverL * 0.9;
  
  // Continue or Stop growing tree?
  if( fholL > 5 )
  { 
    if( fRR >= 6 && fRL >= 6) //Both brach Stop
    {
      p5obj.line(fRight, fEndY, fRight, fNextEndY);
      p5obj.line(fLeft, fEndY, fLeft, fNextEndY);
      //Right leaves
      maru(fRight, fNextEndY-fW/2, fW, fRR);
      maru(fRight-fW*0.5, fNextEndY+fW*0.3, fW*0.6, fRL); //Smaller
      maru(fRight-fW*0.8, fNextEndY+fW*0.8, fW*0.4, fRR); //Smallest
      //Left leaves
      maru(fLeft, fNextEndY-fW/2, fW, fRL);
      maru(fLeft-fW*0.5, fNextEndY+fW*0.3, fW*0.6, fRR); //Smaller
      maru(fLeft-fW*0.8, fNextEndY+fW*0.8, fW*0.4, fRL); //Smallest
    }
    else if( fRR >= 6) //Right branch Stop
    {
      p5obj.line(fRight, fEndY, fRight, fNextEndY);
      //Right leaves
      maru(fRight, fNextEndY-fW/2, fW, fRR);
      maru(fRight-fW*0.5, fNextEndY+fW*0.3, fW*0.6, fRL);
      maru(fRight-fW*0.8, fNextEndY+fW*0.8, fW*0.4, fRR);
      //Left continue
      strangetree(fLeft, fEndY, fverL * 0.75, fholL * 0.5, fsW * 0.75, fW * 0.6);
    }
    else if( fRL >= 6) //Left branch Stop
    {
      p5obj.line(fLeft, fEndY, fLeft, fNextEndY);
      //Left leaves
      maru(fLeft, fNextEndY-fW/2, fW, fRL);
      maru(fLeft-fW*0.5, fNextEndY+fW*0.3, fW*0.6, fRR);
      maru(fLeft-fW*0.8, fNextEndY+fW*0.8, fW*0.4, fRL);
      //Right continue
      strangetree(fRight, fEndY, fverL * 0.75, fholL * 0.5, fsW * 0.75, fW * 0.6);
    }
    else //Both branch Continue
    {
      strangetree(fLeft, fEndY, fverL * 0.75, fholL * 0.5, fsW * 0.75, fW * 0.6);
      strangetree(fRight, fEndY, fverL * 0.75, fholL * 0.5, fsW * 0.75, fW * 0.6);
      //Left leaves on branch
      maru(fLeft, fEndY, fW*0.75, fRL);
      maru(fLeft-fW*0.5, fEndY+fW*0.4, fW*0.2, fRR);
      //Right leaves on branch
      maru(fRight, fEndY, fW*0.75, fRR);
      maru(fRight-fW*0.5, fEndY+fW*0.4, fW*0.2, fRL);
    }
  }
  // End growing tree
  else
  {
    p5obj.line(fLeft, fEndY, fLeft, fEndY - fverL * 0.9);
    p5obj.line(fRight, fEndY, fRight, fEndY - fverL * 0.9);
    //Right leaves
    maru(fRight, fEndY - fverL * 0.9, fW, fRR);
    maru(fRight, fNextEndY-fW*1.5, fW*0.6, fRL);
    //Left leaves
    maru(fLeft, fEndY - fverL * 0.9, fW, fRL);
    maru(fLeft, fNextEndY-fW*1.5, fW*0.6, fRR);
  }
}

//decide leaf color
const maru = (X: number, Y: number, W: number, Random: number) => {
  p5obj.noStroke();
  if (Random == 6 || Random == 0)
  {
    p5obj.fill(0, 0, 0.4, 0.8); //Black
  }
  else if(Random == 7 || Random <= 2)
  {
    p5obj.fill(0, 0.5, 0.9, 0.8); //Red
  }
  else if(Random == 8 || Random <= 4)
  {
    p5obj.fill(185, 0.6, 0.8, 0.8); //Blue
  }
  else if(Random == 9 || Random == 5)
  {
    p5obj.fill(114, 0.5, 0.7, 0.8); //Green
  }
  p5obj.circle(X, Y, W);
}

};

export default sketch;
