// Navigator.tsx

import React, { FC, useState, useEffect } from 'react';
import SideBar from './SideBar';
import './Navigator.css';

interface NavigatorProps  {
  onLinkClicked: (IA: number, currentLayer: number, itemIndex: number) => void;
  onCurLessonClick: () => void;
  sidebarElem: number[];
  sidebarItems: SidebarItem[];
  showToLessonsButton?: boolean;
}

interface SidebarItem {
  label: string;
  key: number;
  IA: number;
  nestedList?: SidebarItem[];
}

export const Navigator: FC<NavigatorProps > = ({ onLinkClicked, onCurLessonClick, sidebarElem, sidebarItems, showToLessonsButton=true }) => {
  const [isSideBarOpen, setIsSideBarOpen] = useState<boolean>(false); // サイドバーの開閉状態を管理する状態
  const [sidebarList, setSidebarList] = useState<SidebarItem[]>();
  const [dispSidebarLayer,setDispSidebarLayer] = useState<number>( ( showToLessonsButton ) ? 0 : 1 ); // あまりよくないけど
  const [LessonText, setLessonText ] = useState<string>();
  const [showSidebar, setShowSidebar] = useState<boolean>(false);
  const [showSidebarnest, setshowSidebarnest] = useState<boolean>(false);
  const [selectedIdxLayer0, setSelectedIdxLayer0] = useState<number>(0);
  
  // リンクがクリックされたときの処理
  const handleLinkClick = (IA: number, itemIndex: number ) => {

    //console.log(`clicked: ${itemIndex}`);
    onLinkClicked(IA,dispSidebarLayer,itemIndex);  // 親へ通知

    // レイヤー更新
    let nextLayer = dispSidebarLayer;
    //sidebarElem[dispSidebarLayer] = selectIdx;
    if( dispSidebarLayer + 1 < sidebarElem.length )        // まだ下に階層がある
    //    !( ( sidebarElem[0] === 0 ) && selectIdx === 0 ) )  // トップレイヤーの最初の項目はもぐらない
    {

      setSelectedIdxLayer0( itemIndex );
      setShowSidebar(false);
      //nextLayer = dispSidebarLayer+1;
      setDispSidebarLayer(dispSidebarLayer+1);
    }
  };

  // 戻るがクリックされた時
  const handleReturnClick = () => {
    setShowSidebar(false);

    if( dispSidebarLayer > 0 )
    {
      setDispSidebarLayer(dispSidebarLayer-1);
    }
    else
    {
      setDispSidebarLayer(dispSidebarLayer+1);
    }
  };
  
  // 現在の授業名がクリックされた時の処理
  const handleCurLessonClick = () => {
    onCurLessonClick();
  };

  // トグルがクリックされたときの処理
  const handleToggleClick = () => {
    setIsSideBarOpen(!isSideBarOpen);
  };

  useEffect(() => {
    setSelectedIdxLayer0(sidebarElem[0]);
    
  }, [sidebarElem])

  useEffect(() => {

    // サイドバー項目
    let lsidebarListAll: SidebarItem[] = sidebarItems;
    
    if( dispSidebarLayer === 0 )
    {
      setSidebarList(lsidebarListAll);
    }
    else
    {
      let sidebarCurrent: SidebarItem = sidebarItems[selectedIdxLayer0];
      if (sidebarCurrent.nestedList) {
        setSidebarList(sidebarCurrent.nestedList);
      }
      else
      {
        // 表示すべきネストが無いので
        setShowSidebar(true);
      }
      // 授業回名
      setLessonText(sidebarCurrent.label);
    }

    setshowSidebarnest( dispSidebarLayer > 0 );
    //console.log(`sidebaritems create`);

  }, [sidebarItems, selectedIdxLayer0, dispSidebarLayer]);

  // サイドバー表示リストが準備完了
  useEffect(() => {
    setShowSidebar(true);
    //console.log(`setShowSidebar(true)`);
  }, [sidebarList])

  return (
    <div className="navigator-style">

      {/* 半透明のボックス */}
      {/*<div className="overlay-box"></div>*/}

      {/* トグルボタン */}
      <button className="toggle-button" onClick={() => handleToggleClick()}>
      {isSideBarOpen ? (
        '×'
      ) : (
        <div className="hamburger-icon">
          <span></span>
          <span></span>
          <span></span>
        </div>
      )}
    </button>
      
      {/* サイドバーコンポーネント */}
      { showSidebar && <SideBar onLinkClicked={handleLinkClick} onCurLessonClick={handleCurLessonClick} onReturnClick={handleReturnClick} isOpen={isSideBarOpen} isReturn={(dispSidebarLayer>0)} dispList={sidebarList} LessonText={LessonText} showToLessonsButton={showToLessonsButton} showNest={showSidebarnest} />}
      
      {/* ホームボタン */}
      {/*<button className="button-home" onClick={() => handleHomeClick(selectedLesson)}>🏠</button>*/}

    </div>
  );
};
