const sketch = (p5obj:any) => {
/**************************************************************
 Sakuhin Caption...
 秒毎に尻尾が左右に揺れ、時間が1分進むと耳がピコッと動きます。
 12時間制で机の上の肉球の数が変わります。
 朝、昼、夕方、夜で魚の骨の絵の色が変わります。
 約3秒以上、10秒以内に一回ランダムなタイミングでまばたきをします。
 キャラを上下にちょっとずつ揺らすことで、呼吸しているように見えるようにしました。
 要所要所chatGPTに助けてもらいました。
 **************************************************************/
/**
 デバッグ機能
 'S'キー：png出力
 'H'キー：時が変わったときのアニメーション再生
 'M'キー：分が変わったときのアニメーション再生
 */

// === 'S'キーを押した時の出力画像名 ===
//  "K3_[クラス][番号]_[苗字].png"
let pngName: String = "K3_A21_Fukushima.png";

// === アニメーション用変数/定数 ===
let angle: number = 0;
let targetAngle: number = 5;
let easing: number = 0.05;
let earEasing: number =1;
let earMaxAngle: number = 10;
let earAngle: number = 0;
let earTargetAngle: number = 0;
let earAnimStep: number = 0;
let earAnimTimer: number = 0;
let animTimer: number = 0;
let tiltDuration: number = 7;
let returnDuration: number = 60;
let tiltEasing: number = 0.2;
let returnEasing: number = 0.05;
let tailAngle: number = 0;
let tailTargetAngle: number = 5;
let tailEasing: number = 0.01;
let defaultEyeballY: number = -3;
let blinkEyeballY: number = -10;
let blinkTimer: number = 0;
let blinkInterval: number =(p5obj.random(180, 600));
let blinkDuration: number = 15;
let isBlinking: boolean = false;
let defaultEyelashY: number = -20;
let closedEyelashY: number = -10;
let baseX: number = 0;
let hourWidth: number = 60;
let totalHours: number = 12;

// === Time Handling ===
let hourCurrent: number;       // 現在の時（0~23）
let minuteCurrent: number;     // 現在の分（0~59）
let secondCurrent: number;     // 現在の秒（0~59）
let deltaTime: number;       // 前フレームからの経過時間（秒,0~1）
let deltaTimePerSec: number; // 前回の秒が切り替わってからの経過時間（秒,0~1）
let isHourAnim: number = 0;    // アニメーションフラグ（1:アニメーション中）
let isMinuteAnim: number = 0;
let isSecondAnim: number = 0;

p5obj.setup = (): void =>
{
  p5obj.createCanvas(400, 300);
  p5obj.frameRate(60);
  p5obj.noStroke();
  p5obj.initTime();
}

p5obj.draw = (): void =>
{
  // === Time Update ===
  p5obj.updateTimePre();
  p5obj.background(40);
  p5obj.picture();


    //////まばたき
    if (!isBlinking) {
      blinkTimer++;
      if (blinkTimer >= blinkInterval) {
        blinkTimer = 0;
        isBlinking = true;
      }
    } else {
      if (isBlinking) {
        blinkTimer++;
let halfDuration: number = blinkDuration / 2;

        if (blinkTimer < halfDuration) {
          eyeHight = 0;
          eyelashY = closedEyelashY;
          eyeballY = blinkEyeballY;
        } else if (blinkTimer < blinkDuration) {
          eyeHight = 17;
          eyelashY = defaultEyelashY;
          eyeballY = defaultEyeballY;
        } else {
          isBlinking = false;
          blinkTimer = 0;
          blinkInterval =(p5obj.random(180, 600));
        }
      } else {
        blinkTimer++;

        if (blinkTimer > blinkInterval) {
          isBlinking = true;
          blinkTimer = 0;
        }
      }
    }
    //////まばたき終わり


    //////尻尾
    if (secondCurrent != secondPrev)
    {
      if (secondCurrent % 1 == 0)
      {
        if (tailTargetAngle > 0)
        {
          tailTargetAngle = -10;
        } else
        {
          tailTargetAngle = 10;
        }
      }
    }
    tailAngle += (tailTargetAngle - tailAngle) * tailEasing;
    p5obj.push();
    p5obj.translate(285, 290 + 5);
    p5obj.rotate(p5obj.radians(tailAngle));
    p5obj.translate(0, -130);
    p5obj.tail();
    p5obj.pop();
    //////尻尾終わり


    //////体上下
let period: number = 6.0;
let amplitude: number = 2;
let timeInSec: number = p5obj.millis() / 1000.0;
let characterYOffset: number = p5obj.sin(p5obj.TWO_PI * timeInSec / period) * amplitude;

    p5obj.push();
    p5obj.translate(285, 160 + characterYOffset);
    p5obj.character();
    p5obj.pop();
    //////体上下終わり


    //////耳
    if (minuteCurrent != minutePrev)
    {
      minutePrev = minuteCurrent;

      earAnimStep = 1;
      earAnimTimer = tiltDuration;
      targetAngle = 10;
    }

    if (earAnimStep == 1)
    {
      angle += (targetAngle - angle) * tiltEasing;
      earAnimTimer--;
      if (earAnimTimer <= 0)
      {
        earAnimStep = 2;
        earAnimTimer = returnDuration;
        targetAngle = 0;
      }
    } else if (earAnimStep == 2)
    {
      angle += (targetAngle - angle) * returnEasing;
      earAnimTimer--;
      if (earAnimTimer <= 0)
      {
        earAnimStep = 0;
        angle = 0;
      }
    }
    p5obj.push();
    p5obj.translate(285, 160 + characterYOffset);
    p5obj.push();
    p5obj.rotate(p5obj.radians(angle));
    p5obj.leftEar();
    p5obj.pop();
    p5obj.push();
    p5obj.rotate(p5obj.radians(-angle));
    p5obj.rightEar();
    p5obj.pop();
    p5obj.pop();
    //////耳終わり


  //////その他
  p5obj.push();
  p5obj.translate(285, 160);
  p5obj.hands();
  p5obj.pop();
  p5obj.desk();
  p5obj.paws();
  //////その他終わり

  /*
   // 時間をデバッグ表示（ 提出前に非表示にすること．）
   p5obj.fill( 0 );
   p5obj.textSize(20);
   p5obj.text( hourCurrent + ":" + minuteCurrent + ":" + secondCurrent, 10, 20);
   p5obj.text( "deltaTimePerSec: " + deltaTimePerSec, 10, 40);
   p5obj.text( "deltaTime: " + deltaTime, 10, 60);
   
   secondPrev = secondCurrent;
   //////時間終わり
   */

  // === Time Update ===
  p5obj.updateTimePost();
}
let eyeHight: number =17;
let eyelashR: number =13;
let eyelashL: number =-35;
let eyelashY: number =-20;
let eyeballY: number =-3;


p5obj.character = (): void =>
{
  p5obj.body();
  p5obj.face();
}

p5obj.face = (): void =>
{
  p5obj.backHair();
  p5obj.skin();
  p5obj.eyes();
  p5obj.frontHair();
}

p5obj.tail = (): void =>
{
  p5obj.noFill();
  p5obj.stroke('#666058');
  p5obj.strokeWeight(8);
  p5obj.bezier(100, -5, -40, -40, 150, 160, 0, 130);
  p5obj.noStroke();
}

p5obj.body = (): void =>
{
  p5obj.fill('#FFE6DB');
  p5obj.rect(-10, 15, 20, 30);

  p5obj.fill('#ab9e7f');
  p5obj.quad(23, 40, 47, 90, -47, 90, -23, 40);
  p5obj.rect(-47, 88, 94, 50);

  p5obj.fill('#936d5f');
  p5obj.rect(-15, 33, 30, 10);
  p5obj.stroke('#826154');
  p5obj.strokeWeight(1.9);
  p5obj.triangle(0, 43, 7, 60, -7, 60);
  p5obj.noStroke();
}

p5obj.backHair = (): void =>
{
  p5obj.fill('#817a70');
  p5obj.ellipse(0, -35, 116, 100);
}

p5obj.rightEar = (): void =>
{
  p5obj.fill('#817a70');
  p5obj.push();
  p5obj.rotate(p5obj.radians(25));
  p5obj.ellipse(-5, -90, 30, 60);
  p5obj.pop();

  p5obj.push();
  p5obj.rotate(p5obj.radians(-7));
  p5obj.ellipse(57, -75, 20, 60);
  p5obj.pop();
}

p5obj.leftEar = (): void =>
{
  p5obj.fill('#817a70');
  p5obj.push();
  p5obj.rotate(p5obj.radians(-25));
  p5obj.ellipse(5, -90, 30, 60);
  p5obj.pop();

  p5obj.push();
  p5obj.rotate(p5obj.radians(7));
  p5obj.ellipse(-57, -75, 20, 60);
  p5obj.pop();
}

p5obj.skin = (): void =>
{
  p5obj.fill('#FFFFFF');
  p5obj.ellipse(0, -2, 100, 60);
  p5obj.noStroke();
  p5obj.ellipse(0, -25, 100, 50);

  p5obj.fill('#FFE6DB');
  p5obj.circle(-30, 6, 24);
  p5obj.circle(30, 6, 24);
}

p5obj.eyes = (): void =>
{
  if (eyelashY < -10) {
    p5obj.fill('#98b8af');
    p5obj.circle(24, eyeballY, -16);

    p5obj.fill('#98b8af');
    p5obj.circle(-24, eyeballY, 16);
  }

  p5obj.fill('#35342d');
  p5obj.rect(32, eyelashY, -16, eyeHight);
  p5obj.rect(eyelashR, eyelashY, 22, 5);

  p5obj.rect(-32, eyelashY, 16, eyeHight);
  p5obj.rect(eyelashL, eyelashY, 22, 5);
}

p5obj.frontHair = (): void =>
{
  p5obj.fill('#817a70');
  p5obj.quad(42, -30, 60, -30, 60, 5, 42, 5);
  p5obj.quad(-42, -30, -60, -30, -60, 5, -42, 5);
  
  p5obj.ellipse(51, 3, 18, 35);
  p5obj.ellipse(-51, 3, 18, 35);
  p5obj.rect(-30, -70, 60, 20);

  p5obj.push();
  p5obj.rotate(p5obj.radians(45));
  p5obj.ellipse(-55, 0, 40, 60);
  p5obj.ellipse(-35, -23, 30, 50);
  p5obj.pop();

  p5obj.push();
  p5obj.rotate(p5obj.radians(-35));
  p5obj.ellipse(55, -10, 40, 60);
  p5obj.pop();

  p5obj.push();
  p5obj.rotate(p5obj.radians(30));
  p5obj.ellipse(-60, 17, 10, 25);
  p5obj.rotate(p5obj.radians(-60));
  p5obj.ellipse(60, 17, 10, 25);
  p5obj.pop();
}

p5obj.hands = (): void =>
{
  p5obj.fill('#817a70');
  p5obj.ellipse(30, 90, 15, 20);
  p5obj.ellipse(40, 90, 15, 20);
  p5obj.ellipse(50, 90, 15, 20);

  p5obj.ellipse(-30, 90, 15, 20);
  p5obj.ellipse(-40, 90, 15, 20);
  p5obj.ellipse(-50, 90, 15, 20);
}

p5obj.picture = (): void =>
{
  p5obj.push();
  p5obj.translate(35, 20);
  p5obj.stroke(150);
  p5obj.line(50, 40, 70, 30);
  p5obj.line(90, 40, 70, 30);
  p5obj.noStroke();
  p5obj.fill(100);
  p5obj.square(30, 40, 80);
let skyColor: number =0;
let h: number = p5obj.hour();
  if (h >= 6 && h < 15 ) {
    skyColor=200;
  } else if (h >= 15 && h < 18) {
    skyColor=150;
  } else if (h >= 18 && h < 20) {
    skyColor=50;
  } else {
    skyColor=0;
  }
  p5obj.fill(skyColor);
  p5obj.square(40, 50, 60);
let bone: number = skyColor > 128 ? 0 : 255;

  p5obj.fill(bone);
  p5obj.arc(60, 80, 18, 20, p5obj.HALF_PI, p5obj.PI + p5obj.HALF_PI, p5obj.PIE);
  p5obj.triangle(83, 80, 89, 73, 89, 87);

  p5obj.fill(skyColor);
  p5obj.circle(56, 80, 5);

  p5obj.noFill();
  p5obj.stroke(bone);
  p5obj.strokeWeight(2);
  p5obj.arc(66, 80, 5, 18, p5obj.HALF_PI, p5obj.PI + p5obj.HALF_PI);
  p5obj.arc(72, 80, 6, 15, p5obj.HALF_PI, p5obj.PI + p5obj.HALF_PI);
  p5obj.arc(79, 80, 7, 11, p5obj.HALF_PI, p5obj.PI + p5obj.HALF_PI);

  p5obj.line(59, 80, 83, 80);
  p5obj.pop();
}

p5obj.desk = (): void =>
{
  p5obj.fill(200);
  p5obj.rect(0, 250, 400, 50);
}

p5obj.paws = (): void => {
let currentHour: number = p5obj.hour() % 12;
  if (currentHour == 0) currentHour = 12;
let iAmpY: number = 11;
let iXInterval: number = 33;

  for( let i = 0; i < currentHour; i++)
  {
    p5obj.push();
let x: number = i * iXInterval;
let y: number = iAmpY * p5obj.sin(p5obj.radians(x));

    p5obj.translate(15 + x, 275 + y);
    
    ///paw start
let pawHight: number = 0;
    p5obj.fill(30);
    p5obj.circle(10, pawHight, 8);
    p5obj.circle(6, pawHight - 8, 7);
    p5obj.circle(6, pawHight + 8, 7);

    p5obj.push();
    p5obj.rotate(p5obj.radians(40));
    p5obj.ellipse(-3, 0, 12, 9);
    p5obj.rotate(p5obj.radians(-80));
    p5obj.ellipse(-3, 0, 12, 9);
    p5obj.pop();
    ///paw end
    p5obj.pop();
  }
}

// === Time Handling ===
let hourPrev: number;
let minutePrev: number;
let secondPrev: number;
let millisCurrent: number;
let millisPrev: number;
let millisPrevSec: number;

// === Time Handling Functions===
p5obj.initTime = (): void =>
{
  hourCurrent = p5obj.hour();
  minuteCurrent = p5obj.minute();
  secondCurrent = p5obj.second();
  millisCurrent = p5obj.millis();
  
  hourPrev = p5obj.hour();
  minutePrev = p5obj.minute();
  secondPrev = p5obj.second();
  millisPrev = p5obj.millis();
  
  millisPrevSec = p5obj.millis();
}
p5obj.updateTimePre = (): void =>
{ 
  if( hourPrev != p5obj.hour() ) hourCurrent = p5obj.hour();
  if( minutePrev != p5obj.minute() ) minuteCurrent = p5obj.minute();
  secondCurrent = p5obj.second();
  millisCurrent = p5obj.millis();
  
  deltaTime = ( millisCurrent - millisPrev ) / 1000;
  
  if ( secondCurrent != secondPrev )
  {
    millisPrevSec = p5obj.millis();
  }
  
  deltaTimePerSec = ( millisCurrent - millisPrevSec ) / 1000;
}
p5obj.updateTimePost = (): void =>
{ 
  hourPrev = hourCurrent;
  minutePrev = minuteCurrent;
  secondPrev = secondCurrent;
  millisPrev = millisCurrent;
}
p5obj.keyPressed = (): void =>
{
  if ( p5obj.key == 's' )
  {
    p5obj.save(pngName);
  }
  else if ( p5obj.key == 'h' )
  {
    hourPrev = -1;
  }
  else if ( p5obj.key == 'm' )
  {
    minutePrev = -1;
  }
}

};

export default sketch;
